def test_regime_engine_rebuild_ensures_schema_before_delete(monkeypatch):
    events = []
    operation_names = []

    class Cursor:
        def execute(self, query, params=None):
            events.append(str(query))

    class Session:
        def __enter__(self):
            return object(), Cursor()

        def __exit__(self, exc_type, exc, tb):
            return False

    frame = pd.DataFrame(
        [
            {
                "asof_date": pd.Timestamp("2026-01-01T00:00:00Z"),
                "regime_name": "STABLE",
            }
        ]
    )
    monkeypatch.setattr(regime_engine, "ensure_regime_table", lambda: events.append("ensure"))
    monkeypatch.setattr(regime_engine, "db_session", lambda: Session())
    monkeypatch.setattr(
        regime_engine,
        "execute_db_operation",
        lambda operation, *, operation_name, **_kwargs: operation_names.append(operation_name) or operation(),
    )
    monkeypatch.setattr(regime_engine, "upsert_to_db", lambda df, *args, **kwargs: events.append(f"upsert:{len(df)}"))

    regime_engine.persist_regime_snapshot(frame, rebuild=True)

    assert events[0] == "ensure"
    assert operation_names == ["regime_engine:delete_rebuild_snapshot"]
    assert any(f"DELETE FROM {regime_engine.TABLE_NAME}" in event for event in events)
    assert events[-1] == "upsert:1"


def test_regime_engine_build_uses_benchmark_lookback_for_narrow_windows(monkeypatch):
    calls: list[dict[str, object]] = []
    from_date = pd.Timestamp("2026-06-15T00:00:00Z")
    to_date = pd.Timestamp("2026-06-18T00:00:00Z")
    macro = pd.DataFrame(
        {
            "asof_date": pd.date_range(from_date, to_date, freq="D", tz="UTC"),
            "vix_close": [18.0, 18.0, 18.0, 18.0],
            "broad_usd_index_ret_20d": [0.0, 0.0, 0.0, 0.0],
            "wti_crude_spot_ret_20d": [0.0, 0.0, 0.0, 0.0],
            "inr_usd_spot_ret_20d": [0.0, 0.0, 0.0, 0.0],
            "gsec_10y_change_20d_bps": [0.0, 0.0, 0.0, 0.0],
            "macro_stress_score": [0.0, 0.0, 0.0, 0.0],
            "macro_risk_state": ["NORMAL", "NORMAL", "NORMAL", "NORMAL"],
            "macro_sizing_multiplier": [1.0, 1.0, 1.0, 1.0],
            "repo_rate": [6.0, 6.0, 6.0, 6.0],
            "macro_usa_freshness_status": ["ok", "ok", "ok", "ok"],
            "bank_rates_freshness_status": ["ok", "ok", "ok", "ok"],
            "cpi_freshness_status": ["ok", "ok", "ok", "ok"],
            "wpi_freshness_status": ["ok", "ok", "ok", "ok"],
            "gsec_curve_freshness_status": ["ok", "ok", "ok", "ok"],
            "new_macro_source_required": [False, False, False, False],
        }
    )

    def fake_load_macro_history(*, start_date=None, to_date=None):
        calls.append({"source": "macro", "start_date": start_date, "to_date": to_date})
        return macro

    def fake_load_benchmark_history(*, benchmark_name, start_date=None, to_date=None):
        calls.append({"source": "benchmark", "start_date": start_date, "to_date": to_date})
        dates = pd.date_range(from_date - pd.Timedelta(days=80), to_date, freq="D", tz="UTC")
        frame = pd.DataFrame({"date": dates, "benchmark_close": range(100, 100 + len(dates))})
        frame["benchmark_ret_20d"] = frame["benchmark_close"].pct_change(20)
        frame["benchmark_ret_60d"] = frame["benchmark_close"].pct_change(60)
        frame["benchmark_dma_50"] = frame["benchmark_close"].rolling(50, min_periods=50).mean()
        frame["benchmark_dma_200"] = frame["benchmark_close"].rolling(200, min_periods=150).mean()
        frame["benchmark_realized_vol_20d"] = 0.1
        frame["benchmark_drawdown_60d"] = 0.0
        return frame

    monkeypatch.setattr(regime_engine, "load_macro_history", fake_load_macro_history)
    monkeypatch.setattr(regime_engine, "load_benchmark_history", fake_load_benchmark_history)

    out = regime_engine.build_regime_snapshot(from_date=from_date, to_date=to_date)

    benchmark_call = next(call for call in calls if call["source"] == "benchmark")
    assert benchmark_call["start_date"] == from_date - pd.Timedelta(days=regime_engine.BENCHMARK_LOOKBACK_BUFFER_DAYS)
    assert out["asof_date"].min() == from_date
    assert out["asof_date"].max() == to_date
    assert out["benchmark_ret_20d"].notna().all()


