    assert kept_by_symbol["AQYLON"]["context_identity_validation_status"] == "resolved_dhan_master_current_symbol"
    assert len(suppressed) == 1
    assert suppressed[0]["symbol"] == "MISSING"
    assert suppressed[0]["context_policy_effect"] == "suppress_context_identity_unresolved_no_trade_authority"


