def test_operator_health_full_mode_dispatches_checks_through_worker_runner(monkeypatch, tmp_path):
    captured: dict[str, object] = {}
    log_dir = tmp_path / "logs"
    log_dir.mkdir()

    def fake_run_health_checks(checks, *, workers):
        captured["workers"] = workers
        captured["check_names"] = list(checks)
        return {name: {"status": "ok", "message": f"{name} ok"} for name in checks}

    monkeypatch.setattr(operator_health, "OPERATOR_HEALTH_FULL_WORKERS", 7)
    monkeypatch.setattr(operator_health, "_run_health_checks", fake_run_health_checks)

    payload = operator_health.build_operator_health(log_dir=log_dir, include_dhan=False, detail_level="full")

    assert payload["detail_level"] == "full"
