    assert "ts_forecast_paper" in captured["check_names"]
    assert "llm_provenance_audit" in captured["check_names"]
    assert "provenance_graph_dry_runs" in captured["check_names"]
    assert "causal_event_memory_evidence" in captured["check_names"]
    assert "theme_sector_alias_coverage" in captured["check_names"]
