def test_operator_health_named_check_subprocess_parses_last_json_line(monkeypatch, tmp_path):
    command_seen = {}

    def fake_run(command, capture_output=True, text=True, timeout=None, check=False):
        command_seen["command"] = command
        command_seen["timeout"] = timeout
        return subprocess.CompletedProcess(command, 0, stdout='debug line\n{"status": "ok", "message": "db ok"}\n', stderr="")

    monkeypatch.setattr(operator_health.subprocess, "run", fake_run)

    payload = operator_health.run_named_health_check_subprocess("database", log_dir=tmp_path, timeout_seconds=4)

    assert payload == {"status": "ok", "message": "db ok"}
    assert command_seen["command"][-2] == "database"
    assert command_seen["command"][-1] == str(tmp_path)
    assert command_seen["timeout"] == 4


