def test_operator_health_feature_stage_gates_warns_on_blocked_inputs(monkeypatch):
    monkeypatch.setattr(operator_health, "table_exists", lambda table_name: table_name == "advisory_action_recommendations")
    monkeypatch.setattr(
        operator_health,
        "sql_to_df",
        lambda *args, **kwargs: pd.DataFrame([{"symbol": "ABC"}, {"symbol": "XYZ"}]),
    )

    def fake_gate(stage, symbols, asof_date=None):
        if stage == "company_memory":
            return {
                "stage": stage,
                "status": "ok",
                "symbols_checked": len(symbols),
                "blocked_count": 0,
                "blocked_symbols": [],
                "required_input_keys": ["daily_ohlcv", "technical_daily", "announcement_evidence", "bhavcopy_evidence"],
                "context_input_keys": ["announcement_context_overlay", "macro_context_overlay"],
                "gate_effect": "review_input_only",
                "symbols": {
                    "ABC": {
                        "symbol": "ABC",
                        "status": "ok",
                        "blockers": [],
                        "required_inputs": [],
                        "context_inputs": [
                            {"input_key": "announcement_context_overlay", "status": "stale", "blocking": False},
                            {"input_key": "macro_context_overlay", "status": "fresh", "blocking": False},
                        ],
                    }
                },
            }
        if stage == "risk":
            return {
                "stage": stage,
                "status": "blocked",
                "symbols_checked": len(symbols),
                "blocked_count": 1,
                "blocked_symbols": ["ABC"],
                "required_input_keys": ["technical_features"],
                "context_input_keys": [],
                "gate_effect": "review_only",
            }
        return {
            "stage": stage,
            "status": "ok",
            "symbols_checked": len(symbols),
            "blocked_count": 0,
            "blocked_symbols": [],
            "required_input_keys": ["technical_features"],
            "context_input_keys": [],
            "gate_effect": "none",
        }

    monkeypatch.setattr(operator_health, "evaluate_stage_feature_gate", fake_gate)

    payload = operator_health.check_feature_stage_gates(limit=10)

    assert payload["status"] == "warn"
    assert payload["blocked_stage_count"] == 1
    assert payload["blocked_symbol_count"] == 1
    assert any(row["stage"] == "risk" and row["status"] == "blocked" for row in payload["rows"])
    company_memory_row = next(row for row in payload["rows"] if row["stage"] == "company_memory")
    assert company_memory_row["status"] == "ok"
    assert company_memory_row["context_input_keys"] == ["announcement_context_overlay", "macro_context_overlay"]
    assert company_memory_row["context_input_status_counts"] == {"stale": 1, "fresh": 1}
    assert company_memory_row["context_warning_count"] == 1


