    assert payload["promotion_review_runtime_block_count"] == 0
    assert payload["promotion_review_harmful_class_block_count"] == 0
    reviews = payload["promotion_reviews"]
    assert reviews["status"] == "ok"
    assert reviews["review_count"] == 1
    assert reviews["broker_execution_allowed"] is False
    assert reviews["policy_auto_promotion_allowed"] is False
    assert reviews["sample_blocked_reviews"][0]["harmful_sectors"] == ["AUTO"]
    assert reviews["sample_blocked_reviews"][0]["authority"] == "research_only_manual_review"
    assert reviews["sample_blocked_reviews"][0]["broker_execution_allowed"] is False
