def test_feature_freshness_tracks_context_overlays_without_hard_stage_gate():
    specs = feature_freshness.FEATURE_INPUT_SPECS_BY_KEY
    context_keys = {
        "announcement_context_overlay",
        "bhavcopy_context_overlay",
        "exchange_context_overlay",
        "news_theme_context_overlay",
        "macro_context_overlay",
    }

    assert context_keys <= set(specs)
    assert all(specs[key].required is False for key in context_keys)
    assert specs["announcement_context_overlay"].symbol_column == "symbol"
    assert specs["bhavcopy_context_overlay"].symbol_column == "symbol"
    assert specs["exchange_context_overlay"].symbol_column == "symbol"
    assert specs["news_theme_context_overlay"].symbol_column is None
    assert specs["macro_context_overlay"].symbol_column is None

    stage_inputs = {
        input_key
        for dependency in feature_freshness.STAGE_FEATURE_DEPENDENCIES
        for input_key in dependency.input_keys
    }
    assert context_keys.isdisjoint(stage_inputs)


def test_feature_freshness_company_memory_context_inputs_are_non_blocking(monkeypatch):
    def fake_evaluate(spec, *, symbol, asof_date):
        context_statuses = {
            "announcement_context_overlay": ("stale", "older_than_freshness_window"),
            "bhavcopy_context_overlay": ("missing", "no_point_in_time_rows"),
            "exchange_context_overlay": ("error", "db_timeout"),
            "news_theme_context_overlay": ("fresh", "within_freshness_window"),
            "macro_context_overlay": ("fresh", "within_freshness_window"),
        }
        status, reason = context_statuses.get(spec.key, ("fresh", "within_freshness_window"))
        return {
            "input_key": spec.key,
            "label": spec.label,
            "status": status,
            "reason": reason,
            "latest_at": "2026-06-09T00:00:00+00:00" if status != "missing" else None,
            "age_days": 1.0 if status != "missing" else None,
            "required": bool(spec.required),
        }

    monkeypatch.setattr(feature_freshness, "evaluate_feature_input", fake_evaluate)

    gate = feature_freshness.evaluate_stage_feature_gate(
        "company_memory",
        ["abc"],
        asof_date=pd.Timestamp("2026-06-10T00:00:00Z"),
    )

    assert gate["status"] == "ok"
    assert gate["blocked_symbols"] == []
    assert gate["required_input_keys"] == [
        "daily_ohlcv",
        "technical_daily",
        "announcement_evidence",
        "bhavcopy_evidence",
    ]
    assert gate["context_input_keys"] == [
        "announcement_context_overlay",
        "bhavcopy_context_overlay",
        "exchange_context_overlay",
        "news_theme_context_overlay",
        "macro_context_overlay",
    ]
    symbol_gate = gate["symbols"]["ABC"]
    assert symbol_gate["status"] == "ok"
    assert symbol_gate["blockers"] == []
    assert len(symbol_gate["required_inputs"]) == 4
    assert len(symbol_gate["context_inputs"]) == 5
    assert {row["status"] for row in symbol_gate["context_inputs"]} >= {"stale", "missing", "error"}
    assert all(row["blocking"] is False for row in symbol_gate["context_inputs"])


