def test_action_evidence_provenance_persist_uses_single_primary_key(monkeypatch):
    calls = []
    rows = pd.DataFrame(
        [
            {
                "provenance_id": "aep_test",
                "asof_date": pd.Timestamp("2026-05-01T00:00:00Z"),
                "symbol": "ABC",
                "action_code": "BUY",
                "evidence_section": "technical",
                "evidence_node_type": "technical_signal",
                "evidence_status": "complete",
                "influence_effect": "explain_only_no_ranking_change",
                "authority_scope": "research_only",
                "policy_effect": "provenance_audit_only_no_trade_authority",
                "broker_execution_allowed": False,
                "policy_auto_promotion_allowed": False,
                "load_ts": pd.Timestamp("2026-05-01T00:00:00Z"),
            }
        ]
    )
    monkeypatch.setattr(action_evidence_provenance, "ensure_table", lambda: None)
    deletes = []
    monkeypatch.setattr(action_evidence_provenance, "execute_db_operation", lambda func, **kwargs: deletes.append(kwargs) or 0)
    monkeypatch.setattr(
        action_evidence_provenance,
        "upsert_to_db",
        lambda frame, table, unique_keys, **kwargs: calls.append((table, list(unique_keys), kwargs)),
    )

    action_evidence_provenance.persist_provenance(rows)

    assert deletes[0]["operation_name"] == "action_evidence_provenance:delete_rebuilt_action_keys"
    assert calls[0][0] == action_evidence_provenance.TABLE_NAME
    assert calls[0][1] == ["provenance_id"]
    assert "timescaledb_column" not in calls[0][2]


