def test_action_recommender_reason_contract_repair_updates_metadata_only(monkeypatch):
    asof_date = pd.Timestamp("2026-05-01T00:00:00Z")
    rows = pd.DataFrame(
        [
            {
                "asof_date": asof_date,
                "published_on": pd.Timestamp("2026-05-01T09:30:00Z"),
                "symbol": "ABC",
                "setup_id": "EVENT",
                "unique_id": "EVT-1",
                "action_code": "WATCH",
                "action_priority": action_recommender.ACTION_PRIORITY["WATCH"],
                "action_source": "event_policy",
                "source_action": "BUY_WATCH",
                "transaction_type": None,
                "execution_mode": "review_only",
                "action_reason": "Order win supports watch pressure.",
                "raw_context_json": "{}",
            }
        ]
    )
    executed = []
    monkeypatch.setattr(action_recommender, "_load_action_recommendations_for_reason_repair", lambda **_kwargs: rows.copy())
    monkeypatch.setattr(action_recommender, "enrich_action_candidate_context", lambda df, **_kwargs: df.copy())
    monkeypatch.setattr(action_recommender, "execute_db_operation", lambda operation, **kwargs: executed.append(kwargs) or operation())

    class FakeCursor:
        def execute(self, query, params=None):
            executed.append({"query": query, "params": params})

    class FakeSession:
        def __enter__(self):
            return (None, FakeCursor())

        def __exit__(self, exc_type, exc, tb):
            return False

    monkeypatch.setattr(action_recommender, "db_session", lambda: FakeSession())

    _repaired, meta = action_recommender.repair_action_reason_contracts(dry_run=False, limit=10)

    assert meta["persisted"] is True
    update_call = next(item for item in executed if isinstance(item, dict) and "query" in item)
    assert "SET raw_context_json = %s" in update_call["query"]
    assert "recommendation_reason_json = %s" in update_call["query"]
    assert "reason_contract_status = %s" in update_call["query"]
    assert "action_code" not in update_call["query"].split("SET", 1)[1].split("WHERE", 1)[0]


def test_action_recommender_reason_contract_repair_market_context_is_annotation_only(monkeypatch):
    asof_date = pd.Timestamp("2026-05-01T00:00:00Z")
    rows = pd.DataFrame(
        [
            {
                "asof_date": asof_date,
                "published_on": pd.Timestamp("2026-05-01T09:30:00Z"),
                "symbol": "ABC",
                "setup_id": "PORTFOLIO",
                "unique_id": "ABC-1",
                "action_code": "BUY",
                "action_priority": action_recommender.ACTION_PRIORITY["BUY"],
                "action_source": "portfolio",
                "source_action": "BUY",
                "transaction_type": "BUY",
                "execution_mode": "broker_order",
                "approved_allocation_inr": 100000.0,
                "action_fraction": 1.0,
                "invest_score_pct": 80.0,
                "action_reason": "Portfolio approved entry.",
                "raw_context_json": "{}",
            }
        ]
    )
    monkeypatch.setattr(action_recommender, "_load_action_recommendations_for_reason_repair", lambda **_kwargs: rows.copy())
    monkeypatch.setattr(action_recommender, "enrich_action_candidate_context", lambda df, **_kwargs: df.copy())
    monkeypatch.setattr(
        action_recommender,
        "load_latest_market_context",
        lambda *args, **kwargs: {
            "summary": {
                "regime_name": "RISK_OFF",
                "macro_risk_state": "NORMAL",
                "breadth_trend_alignment_pct": 20.0,
                "risk_off_score": 0.95,
            },
            "top_universe": [],
        },
    )

    repaired = action_recommender._build_reason_contract_repair_frame(rows)
    context = json.loads(repaired.iloc[0]["raw_context_json"])
    contract = json.loads(repaired.iloc[0]["recommendation_reason_json"])
    macro = contract["evidence"]["macro_regime"]

    assert repaired.iloc[0]["action_code"] == "BUY"
    assert repaired.iloc[0]["transaction_type"] == "BUY"
    assert repaired.iloc[0]["execution_mode"] == "broker_order"
    assert repaired.iloc[0]["approved_allocation_inr"] == 100000.0
    assert context["market_context_adjustment_json"]["adjustment"] == "positive_action_size_reduced_by_market_context"
    assert macro["market_context_adjustment"] == "positive_action_size_reduced_by_market_context"
    assert macro["size_multiplier"] < 1.0
    assert macro["multi_context_diagnostics"]["breadth_context"]["label"] == "weak_breadth"
    assert macro["multi_context_diagnostics"]["macro_stress_context"]["label"] == "risk_off_score_high"

    _repaired, meta = action_recommender.repair_action_reason_contracts(dry_run=True, limit=10)

    assert meta["persisted"] is False
    assert meta["policy_effect"] == "reason_contract_metadata_repair_only_no_action_or_ranking_change"
    assert meta["broker_execution_allowed"] is False
    assert meta["multi_context_label_coverage_before"]["missing_label_total"] == 5
    assert meta["multi_context_label_coverage_after"]["missing_label_total"] == 0
    assert meta["multi_context_missing_label_delta"] == 5


def test_action_recommender_reason_contract_explains_same_symbol_source_precedence(monkeypatch):
    monkeypatch.setattr(action_recommender, "load_enabled_conflict_rule_ids", lambda: set(action_recommender.DEFAULT_CONFLICT_RULE_IDS))
    asof_date = pd.Timestamp("2026-05-01T00:00:00Z")
    candidates = pd.DataFrame(
        [
            {
                "asof_date": asof_date,
                "published_on": pd.Timestamp("2026-05-01T10:00:00Z"),
                "symbol": "TCS",
                "setup_id": "LIFE",
                "unique_id": "pos-1",
                "action_code": "SELL",
                "action_priority": 100,
                "action_source": "rebalance",
                "source_action": "exit_stop",
                "transaction_type": "SELL",
                "execution_mode": "broker_order",
                "reference_price": 124.0,
                "stop_price": 125.0,
                "action_reason": "Stop hit after close below risk level.",
                "action_detail": "exit_stop",
                "raw_context_json": json.dumps({"suggested_action": "exit_stop", "lifecycle_reason": "Stop hit.", "position_status": "open"}),
                "load_ts": asof_date,
            },
            {
                "asof_date": asof_date,
                "published_on": pd.Timestamp("2026-05-01T10:05:00Z"),
                "symbol": "TCS",
                "setup_id": "PORT",
                "unique_id": "buy-1",
                "action_code": "BUY",
                "action_priority": 50,
                "action_source": "portfolio",
                "source_action": "approved",
                "transaction_type": "BUY",
                "execution_mode": "broker_order",
                "stop_price": 118.0,
                "action_reason": "Portfolio model still likes the breakout.",
                "raw_context_json": json.dumps({"technical_state": "BUY_TRIGGERED"}),
                "load_ts": asof_date,
            },
        ]
    )

    winners = action_recommender.rank_action_candidates(candidates)
    with_contract = action_recommender.add_recommendation_reason_contracts(winners, candidates)
    contract = json.loads(with_contract.iloc[0]["recommendation_reason_json"])
    conflict = contract["evidence"]["conflict_resolution"]

    assert with_contract.iloc[0]["action_code"] == "SELL"
    assert with_contract.iloc[0]["reason_contract_status"] == "complete"
    assert "conflict_resolution" in contract["evidence_sections_present"]
    assert conflict["same_symbol_conflict_count"] == 1
    assert conflict["winning_action_source"] == "rebalance"
    assert conflict["losing_candidates"][0]["action_source"] == "portfolio"
    assert "deterministic action priority" in conflict["source_precedence_reason"]


