    assert event_policy_reason["event_tensor"]["event_type"] == "ORDER_WIN"
    assert event_policy_reason["final_action_type"] == "BUY_WATCH"
    assert event_policy_reason["authority_contract"]["broker_execution_allowed"] is False
    assert event_policy_reason["authority_contract"]["requires_technical_confirmation_for_entry"] is True
    identity = event_policy_reason["affected_peer_identity"]
    assert identity["status"] == "requires_identity_validation"
    assert identity["validated_affected_peers"] == ["INFY"]
    assert identity["unresolved_affected_peers"] == ["WIPRO"]
    assert identity["requires_company_master_resolution"] is True
    assert identity["policy_effect"] == "unresolved_peers_context_only_until_validated"
    assert identity["portfolio_authority"] == "none"
    assert identity["broker_execution_allowed"] is False


