    monkeypatch.setattr(signal_refresh, "load_negative_macro_context_exposure_targets", lambda **_kwargs: pd.DataFrame())
    monkeypatch.setattr(signal_refresh, "load_negative_direct_context_exposure_targets", lambda **_kwargs: pd.DataFrame([{"symbol": "XYZ"}]))
    monkeypatch.setattr(signal_refresh, "load_positive_context_overlay_watch_targets", lambda **_kwargs: pd.DataFrame([{"symbol": "abc"}]))
    monkeypatch.setattr(signal_refresh, "load_causal_memory_signal_targets", lambda **_kwargs: (pd.DataFrame(), {"status": "ok", "target_rows": 0}))
    monkeypatch.setattr(signal_refresh, "_filter_negative_context_targets_by_reliability", lambda df, **_kwargs: (df, []))
