def test_action_recommender_cli_result_uses_compact_sample_by_default():
    df = pd.DataFrame(
        [
            {
                "asof_date": pd.Timestamp("2026-06-21T00:00:00Z"),
                "published_on": pd.Timestamp("2026-06-21T10:00:00Z"),
                "symbol": "ABC",
                "setup_id": "SIGNAL_REFRESH_REVIEW",
                "action_code": "WATCH",
                "action_source": "signal_refresh",
                "source_action": "BUY",
                "transaction_type": None,
                "execution_mode": "review_only",
                "authority_scope": "review_input_only",
                "portfolio_authority": "none",
                "broker_execution_allowed": False,
                "full_advisory_required": True,
                "invest_score_pct": 72.0,
                "reference_price": 123.45,
                "reason_contract_status": "complete",
                "action_reason": "Fresh watcher evidence was positive but needs technical confirmation before any broker-capable action.",
                "raw_context_json": json.dumps({"large": "payload"}),
                "recommendation_reason_json": json.dumps({"large": "reason"}),
            }
        ]
    )

    result = action_recommender.build_cli_result(df, dry_run=True, sample_limit=1)

    assert result["sample_mode"] == "compact"
    assert result["action_counts"] == {"WATCH": 1}
    assert result["action_source_counts"] == {"signal_refresh": 1}
    assert result["authority_summary"]["policy_boundary"] == "review_only_no_broker"
    assert result["authority_summary"]["review_only_rows"] == 1
    assert result["authority_summary"]["broker_execution_allowed_rows"] == 0
    assert result["authority_summary"]["full_advisory_required_rows"] == 1
    assert result["authority_summary"]["authority_scope_counts"] == {"review_input_only": 1}
    assert result["authority_summary"]["portfolio_authority_counts"] == {"none": 1}
    assert result["sample"][0]["authority_scope"] == "review_input_only"
    assert result["sample"][0]["broker_execution_allowed"] is False
    assert result["sample"][0]["full_advisory_required"] is True
    assert "raw_context_json" not in result["sample"][0]
    assert "recommendation_reason_json" not in result["sample"][0]
    assert "raw_context_json" in result["omitted_sample_fields"]
    text = action_recommender.format_cli_text(result)
    assert "Action Recommender" in text
    assert "Authority: boundary=review_only_no_broker" in text
    assert "broker_allowed=0" in text
    assert "full_advisory_required=1" in text
    assert "ABC: WATCH from signal_refresh" in text


