def test_action_recommender_deferred_feature_freshness_blocks_positive_broker_action():
    df = pd.DataFrame(
        [
            {
                "symbol": "ABC",
                "action_code": "BUY",
                "action_priority": action_recommender.ACTION_PRIORITY["BUY"],
                "action_source": "portfolio",
                "transaction_type": "BUY",
                "execution_mode": "broker_order",
                "raw_context_json": "{}",
            }
        ]
    )

    with_deferred = action_recommender.add_deferred_feature_freshness_contracts(df)
    gated = action_recommender.apply_feature_freshness_gates(with_deferred)

    assert gated["action_code"].iloc[0] == "MANUAL_REVIEW"
    assert gated["execution_mode"].iloc[0] == "review_only"
    contract = json.loads(with_deferred["feature_freshness_json"].iloc[0])
    assert contract["status"] == "blocked"
