def test_action_recommender_event_policy_reduce_exposure_is_specific_review_only_derisk(monkeypatch):
    monkeypatch.setattr(action_recommender, "load_enabled_conflict_rule_ids", lambda: set(action_recommender.DEFAULT_CONFLICT_RULE_IDS))
    monkeypatch.setattr(action_recommender, "load_enabled_dynamic_conflict_rules_for_ranking", lambda: [])
    asof_date = pd.Timestamp("2026-05-01T00:00:00Z")
    policies = pd.DataFrame(
        [
            {
                "asof_date": asof_date,
                "published_on": pd.Timestamp("2026-05-01T10:00:00Z"),
                "symbol": "TCS",
                "setup_id": "EVENT",
                "unique_id": "EVT-RISK",
                "action_type": "REDUCE_EXPOSURE_REVIEW",
                "policy_class": "REGULATORY_NOTICE",
                "confidence": 0.76,
                "policy_score": -0.31,
                "action_reason": "Regulatory notice weakens the thesis; review exposure.",
                "action_detail": "Use as de-risk pressure only; full advisory/lifecycle confirmation required.",
                "checks_json": json.dumps([{"check_type": "exposure_review", "blocking": True}]),
                "operator_notes_json": json.dumps(
                    {
                        "final_action_type": "REDUCE_EXPOSURE_REVIEW",
                        "operator_summary": "Regulatory notice supports de-risk review.",
                        "possible_action": "Review exposure until lifecycle confirms.",
                        "wait_for_events": ["Company clarification"],
                        "operator_questions": ["Does the notice affect licensing?"],
                        "authority_contract": event_policy.EVENT_POLICY_LLM_AUTHORITY_CONTRACT,
                    }
                ),
                "llm_review_status": "ok",
                "llm_prompt_id": event_policy.PROMPT_ID,
                "llm_prompt_version": event_policy.PROMPT_VERSION,
                "raw_context_json": json.dumps({"event_class": "REGULATORY_NOTICE", "setup_effect": "weakens"}),
                "actionability_json": json.dumps({"review_priority": "high", "materiality": "medium"}),
            }
        ]
    )
    monkeypatch.setattr(action_recommender, "load_event_policy_actions", lambda **_kwargs: policies.copy())

    event_candidates = action_recommender.build_event_policy_action_candidates(asof_date=asof_date)
    assert event_candidates[0]["action_code"] == "REDUCE_EXPOSURE_REVIEW"
    assert event_candidates[0]["action_priority"] == action_recommender.ACTION_PRIORITY["REDUCE_EXPOSURE_REVIEW"]
    assert event_candidates[0]["execution_mode"] == "review_only"
    assert event_candidates[0]["transaction_type"] is None
    raw_context = json.loads(event_candidates[0]["raw_context_json"])
    assert raw_context["source_table"] == action_recommender.EVENT_POLICY_TABLE
    assert raw_context["source_key"] == "EVT-RISK"
    assert raw_context["event_policy_action_mapping"]["mapping_changed"] is True
    assert raw_context["event_policy_action_mapping"]["authority_scope"] == "review_input_only"
    assert raw_context["event_policy_action_mapping"]["broker_execution_allowed"] is False

    candidates = pd.DataFrame(
        [
            *event_candidates,
            {
                "asof_date": asof_date,
                "published_on": pd.Timestamp("2026-05-01T10:15:00Z"),
                "symbol": "TCS",
                "setup_id": "BUY",
                "unique_id": "BUY-1",
                "action_code": "BUY",
                "action_priority": 50,
                "action_source": "portfolio",
                "source_action": "approved",
                "transaction_type": "BUY",
                "execution_mode": "broker_order",
                "stop_price": 118.0,
                "action_reason": "Portfolio model approves the breakout entry.",
                "raw_context_json": json.dumps({"technical_state": "BUY_TRIGGERED", "source_screener_slug": "breakouts"}),
                "load_ts": asof_date,
            },
        ]
    )

    winners = action_recommender.rank_action_candidates(candidates)
    with_contract = action_recommender.add_recommendation_reason_contracts(winners, candidates)
    contract = json.loads(with_contract.iloc[0]["recommendation_reason_json"])
    conflict = contract["evidence"]["conflict_resolution"]
    transition = contract["evidence"]["action_transition"]

    assert with_contract.iloc[0]["action_code"] == "REDUCE_EXPOSURE_REVIEW"
    assert with_contract.iloc[0]["reason_contract_status"] == "complete"
    assert transition["broker_execution_allowed"] is False
    assert transition["broker_order_candidate"] is False
    assert transition["next_required_stage"] == "full_advisory_or_lifecycle_risk_review"
    event_policy_reason = contract["evidence"]["event_policy"]
    assert event_policy_reason["final_action_type"] == "REDUCE_EXPOSURE_REVIEW"
    assert event_policy_reason["authority_contract"]["broker_execution_allowed"] is False
    assert event_policy_reason["authority_contract"]["requires_lifecycle_confirmation_for_exit_or_derisk"] is True
    assert conflict["winning_action_code"] == "REDUCE_EXPOSURE_REVIEW"
    assert conflict["conflict_precedence_rule_id"] == "EXIT_BEATS_ENTRY_OR_WATCH"
    assert conflict["losing_candidates"][0]["action_code"] == "BUY"


