def test_action_recommender_context_overlay_summary_attaches_research_family_reliability():
    rows = pd.DataFrame(
        [
            {
                "symbol": "TCS",
                "context_asof_date": pd.Timestamp("2026-05-01T00:00:00Z"),
                "context_source": "announcement_context",
                "overlay_id": "a1",
                "direction": "positive",
                "pressure_score": 0.8,
                "context_class": "ORDER_WIN",
                "reason": "Order win supports watchlist pressure.",
            },
            {
                "symbol": "TCS",
                "context_asof_date": pd.Timestamp("2026-05-01T00:00:00Z"),
                "context_source": "macro_context",
                "overlay_id": "m1",
                "direction": "negative",
                "pressure_score": 0.6,
                "context_class": "CRUDE_INPUT_COST_PRESSURE",
                "reason": "Input cost pressure offsets the thesis.",
            },
        ]
    )
    reliability = {
        "schema_version": 1,
        "authority_scope": "research_only",
        "action_policy_effect": "annotation_only_no_ranking_change",
        "broker_execution_allowed": False,
        "status": "ok",
        "evaluated_at": "2026-05-02T00:00:00+00:00",
        "candidate_helpful_families": ["announcement_context"],
        "families": {
            "announcement_context": {
                "classification": "candidate_helpful",
                "total_selected_count": 42,
                "total_matured_count": 35,
                "avg_lift_vs_technical_only": 0.021,
                "avg_forward_return_after_cost": 0.018,
                "avg_hit_rate_after_cost": 0.58,
                "context_class_diagnostics": [
                    {"context_class": "ORDER_WIN", "classification": "candidate_helpful"},
                    {"context_class": "DIVIDEND", "classification": "hurts_or_no_lift"},
                ],
            },
            "macro_context": {
                "classification": "needs_more_data",
                "total_selected_count": 4,
                "total_matured_count": 2,
                "avg_lift_vs_technical_only": None,
                "avg_forward_return_after_cost": None,
                "avg_hit_rate_after_cost": None,
            },
        },
    }

    summary = action_recommender._summarize_action_context_overlays(
        rows,
        source_family_reliability=reliability,
    )["TCS"]

    assert summary["action_policy_effect"] == "explain_only_no_ranking_change"
    assert summary["source_family_reliability_policy_effect"] == "annotation_only_no_ranking_change"
    assert summary["broker_execution_allowed"] is False
    assert summary["source_family_reliability_status"] == "ok"
    assert summary["candidate_helpful_source_families"] == ["announcement_context"]
    assert summary["source_family_reliability"]["announcement_context"]["classification"] == "candidate_helpful"
    assert summary["source_family_reliability"]["announcement_context"]["context_class_diagnostics"][1]["context_class"] == "DIVIDEND"
    assert summary["source_family_reliability"]["macro_context"]["classification"] == "needs_more_data"
    assert summary["context_class_reliability_policy_effect"] == "annotation_only_no_ranking_change"
    assert summary["context_class_reliability_counts"]["candidate_helpful"] == 1
    assert summary["context_class_reliability"][0]["context_class"] == "ORDER_WIN"
    assert summary["context_class_reliability"][0]["classification"] == "candidate_helpful"
    assert summary["context_class_reliability"][0]["broker_execution_allowed"] is False
    assert summary["top_overlays"][0]["source_family_reliability"]["classification"] in {"candidate_helpful", "needs_more_data"}
    helpful_overlay = next(row for row in summary["top_overlays"] if row["source"] == "announcement_context")
    assert helpful_overlay["context_class_reliability"]["classification"] == "candidate_helpful"
    assert helpful_overlay["context_class_reliability"]["action_policy_effect"] == "annotation_only_no_ranking_change"


