def test_recommendation_diagnostics_context_overlay_reliability_contracts():
    fresh = recommendation_diagnostics.summarize_context_overlay_reliability(
        {
            "status": "ok",
            "evaluated_at": pd.Timestamp.utcnow(),
            "families": [
                {"source_family": "announcement_context", "classification": "candidate_helpful"},
                {"source_family": "bhavcopy_context", "classification": "protective_candidate"},
                {"source_family": "macro_context", "classification": "needs_benchmark_attribution"},
                {"source_family": "exchange_context", "classification": "benchmark_beta_not_overlay_alpha"},
            ],
            "best_family": {"source_family": "announcement_context", "classification": "candidate_helpful"},
        }
    )

    assert fresh["status"] == "ok_fresh"
    assert fresh["runtime_usable_family_count"] == 2
    assert fresh["suppressed_or_split_required_count"] == 2
    assert fresh["classification_counts"]["benchmark_beta_not_overlay_alpha"] == 1
    assert fresh["recommended_commands"] == []
    assert fresh["policy_boundary"]["broker_execution_allowed"] is False

    stale = recommendation_diagnostics.summarize_context_overlay_reliability(
        {
            "status": "ok",
            "evaluated_at": pd.Timestamp.utcnow() - pd.Timedelta(days=recommendation_diagnostics.CONTEXT_RELIABILITY_MAX_AGE_DAYS + 1),
            "families": [],
        }
    )
    assert stale["status"] == "stale"
    assert [item["command"] for item in stale["recommended_commands"]] == [
        "./all_ml.sh --run-signal-quality-window-runner --include-signal-quality-split-reports",
        "python -m advisory.context_overlay_reliability_report --horizons 5 10 20 --format text",
    ]

    unavailable = recommendation_diagnostics.summarize_context_overlay_reliability({"status": "evidence_unavailable", "families": []})
    assert unavailable["status"] == "evidence_unavailable"
    assert unavailable["runtime_usable_family_count"] == 0
    assert unavailable["recommended_commands"]


def test_recommendation_diagnostics_context_reliability_reports_latest_after_asof(monkeypatch):
    calls = []

    def fake_load_persisted_reliability_report(*, asof_date=None, evaluated_at=None):
        calls.append({"asof_date": asof_date, "evaluated_at": evaluated_at})
        if asof_date is not None:
            return {"status": "no_data", "families": [], "evaluated_at": None}
        return {
            "status": "needs_more_data",
            "evaluated_at": pd.Timestamp("2026-06-21T00:00:00Z"),
            "families": [{"source_family": "exchange_context", "classification": "needs_more_data", "total_matured_count": 0}],
        }

    monkeypatch.setattr(recommendation_diagnostics, "load_persisted_reliability_report", fake_load_persisted_reliability_report)

    payload = recommendation_diagnostics.load_context_overlay_reliability_for_diagnostics(asof_date=pd.Timestamp("2026-06-16T00:00:00Z"))

    assert payload["status"] == "no_point_in_time_evidence_latest_available"
    assert payload["latest_available_after_asof"]["status"] == "needs_more_data"
    assert payload["latest_available_after_asof"]["evaluated_at"] == "2026-06-21T00:00:00+00:00"
    assert "do not use newer evidence to judge older decisions" in payload["operator_action"]
