    rows = [
        {
            "symbol": "ABC",
            "action_code": "MANUAL_REVIEW",
            "action_source": "event_policy",
            "action_reason": "Resolved to watch evidence.",
            "feature_blocker_count": 0,
            "suppression_reasons": [],
            "manual_review": {
                "boundary": "event_policy_review_required",
                "source_action": "BUY_WATCH",
                "review_reason": "no_material_adversarial_issue",
            },
            "market_context": {},
        },
        {
            "symbol": "XYZ",
            "action_code": "MANUAL_REVIEW",
            "action_source": "event_policy",
            "action_reason": "Needs classification.",
            "feature_blocker_count": 0,
            "suppression_reasons": [],
            "manual_review": {
                "boundary": "event_policy_review_required",
                "source_action": "MANUAL_REVIEW",
                "review_reason": "llm_review_manual",
            },
            "market_context": {},
        },
        {
            "symbol": "DEF",
            "action_code": "MANUAL_REVIEW",
            "action_source": "portfolio",
            "action_reason": "Legacy market block.",
            "feature_blocker_count": 0,
            "suppression_reasons": ["market_context_blocked"],
            "manual_review": {
                "boundary": "market_context_positive_action_review_required",
                "source_action": "approved",
            },
            "market_context": {"block_reason": "legacy_regime_label_block"},
        },
    ]

