    assert payload["automation_targets"]["keep_review_only_no_human_trade_decision"] == 1
    assert [item["command"] for item in payload["recommended_commands"]] == [
        "./all_advisory.sh",
        "python -m advisory.recommendation_diagnostics --format json",
    ]
    assert payload["policy_boundary"]["broker_execution_allowed"] is False


