def test_recommendation_diagnostics_summarizes_upstream_constructive_candidates():
    asof_date = pd.Timestamp("2026-05-01T00:00:00Z")
    action_rows = pd.DataFrame(
        [
            {
                "asof_date": asof_date,
                "symbol": "ABC",
                "action_code": "WATCH",
                "action_source": "watchlist",
                "execution_mode": "review_only",
                "reason_contract_status": "complete",
                "raw_context_json": "{}",
                "recommendation_reason_json": "{}",
                "load_ts": pd.Timestamp("2030-01-01T00:00:00Z"),
            }
        ]
    )
    candidate_rows = pd.DataFrame(
        [
            {
                "asof_date": asof_date,
                "symbol": "ABC",
                "setup_id": "TECH_BREAKOUT",
                "candidate_state": "PASS_NOW",
                "technical_state": "BUY_TRIGGERED",
                "technical_trigger_type": "breakout",
                "rule_pass": True,
                "watch_enabled": True,
                "setup_score": 82.0,
                "technical_score": 86.0,
                "watch_reason_detail": "Breakout confirmed.",
                "load_ts": pd.Timestamp("2030-01-01T00:00:00Z"),
            }
        ]
    )
    rejection_rows = pd.DataFrame(
        [
            {
                "asof_date": asof_date,
                "symbol": "XYZ",
                "setup_id": "TECH_BREAKOUT",
                "reason_code": "low_liquidity",
                "severity": "hard",
            }
        ]
    )

    payload = recommendation_diagnostics.summarize_recommendation_rows(
        action_rows,
        candidates=candidate_rows,
        rejections=rejection_rows,
    )

    upstream = payload["upstream_candidates"]
    assert payload["no_buy_diagnosis"] == "confirmed_technical_candidates_lost_downstream"
    assert upstream["positive_or_constructive_candidate_count"] == 1
    assert upstream["positive_candidate_final_action_counts"] == {"WATCH": 1}
    assert upstream["pass_now_with_technical_ignore_count"] == 0
    assert upstream["technical_entry_readiness"]["confirmed_entry_candidate_count"] == 1
    assert upstream["technical_entry_readiness"]["diagnosis"] == "technical_entry_confirmed_candidates_available"
    assert upstream["technical_entry_readiness"]["archetype_readiness"][0]["technical_setup_archetype"] == "breakout"
    assert upstream["technical_entry_readiness"]["archetype_readiness"][0]["confirmed_entry_count"] == 1
    assert upstream["confirmed_entry_lost_downstream_samples"][0]["technical_setup_archetype"] == "breakout"
    assert upstream["confirmed_entry_final_action_counts"] == {"WATCH": 1}
    assert upstream["confirmed_entry_lost_downstream_count"] == 1
    assert upstream["confirmed_entry_lost_downstream_samples"][0]["symbol"] == "ABC"
    assert payload["primary_no_buy_cause"]["code"] == "confirmed_technical_candidates_lost_downstream"
    assert payload["primary_no_buy_cause"]["evidence"]["confirmed_entry_lost_downstream_count"] == 1
    assert payload["primary_no_buy_cause"]["safe_to_tune_policy"] is False
    assert upstream["candidate_state_counts"] == {"PASS_NOW": 1}
    assert upstream["technical_state_counts"] == {"BUY_TRIGGERED": 1}
    assert upstream["rejection_reason_counts"] == {"low_liquidity": 1}
    assert upstream["top_positive_or_constructive_candidates"][0]["symbol"] == "ABC"
    assert upstream["top_positive_or_constructive_candidates"][0]["final_action"] == "WATCH"
    assert any("Upstream constructive candidates exist" in step for step in payload["operator_next_steps"])
    assert any("Confirmed technical entry candidates were downgraded downstream" in step for step in payload["operator_next_steps"])


def test_recommendation_diagnostics_surfaces_transition_policy_gate_downgrade():
    asof_date = pd.Timestamp("2026-05-01T00:00:00Z")
    action_rows = pd.DataFrame(
        [
            {
                "asof_date": asof_date,
                "symbol": "ABC",
                "setup_id": "TECH_BREAKOUT",
                "action_code": "WATCH",
                "action_source": "technical",
                "execution_mode": "review_only",
                "reason_contract_status": "complete",
                "action_reason": "BUY downgraded to WATCH because transition confirmation is unstable.",
                "raw_context_json": "{}",
                "recommendation_reason_json": json.dumps(
                    {
                        "status": "transition_downgraded",
                        "transition_policy_gate": {
                            "gate": "action_transition_stability",
                            "original_action_code": "BUY",
                            "downgraded_action_code": "WATCH",
                            "stability_status": "unstable_requires_deterministic_confirmation",
                            "transition_blockers": ["entry_after_exit_without_fresh_technical_confirmation"],
                            "policy_effect": "downgrade_to_review_only_signal_no_broker_execution",
                            "broker_execution_allowed": False,
                            "portfolio_authority": "none",
                            "full_advisory_required": True,
                        },
                        "evidence": {},
                    }
                ),
                "load_ts": pd.Timestamp("2030-01-01T00:00:00Z"),
            }
        ]
    )
    candidate_rows = pd.DataFrame(
        [
            {
                "asof_date": asof_date,
                "symbol": "ABC",
                "setup_id": "TECH_BREAKOUT",
                "candidate_state": "WATCH_BREAKOUT",
                "technical_state": "NEAR_PIVOT",
                "technical_trigger_type": "near_pivot",
                "rule_pass": True,
                "watch_enabled": True,
                "setup_score": 74.0,
                "technical_score": 73.0,
                "load_ts": pd.Timestamp("2030-01-01T00:00:00Z"),
            }
        ]
    )

    payload = recommendation_diagnostics.summarize_recommendation_rows(
        action_rows,
        candidates=candidate_rows,
        rejections=pd.DataFrame(),
    )

    assert payload["no_buy_diagnosis"] == "transition_stability_policy_gate_downgraded_broker_actions"
    assert payload["primary_no_buy_cause"]["code"] == "transition_stability_policy_gate_downgraded_broker_actions"
    assert payload["suppression_counts"]["transition_stability_downgraded"] == 1
    gates = payload["transition_policy_gates"]
    assert gates["transition_policy_gate_count"] == 1
    assert gates["original_action_counts"] == {"BUY": 1}
    assert gates["downgraded_action_counts"] == {"WATCH": 1}
    assert gates["transition_blocker_counts"]["entry_after_exit_without_fresh_technical_confirmation"] == 1
    assert gates["policy_boundary"]["broker_execution_allowed"] is False
    assert any("action-transition stability" in step for step in payload["operator_next_steps"])
    text = recommendation_diagnostics.format_text(payload)
    assert "Transition policy gates:" in text
    assert "entry_after_exit_without_fresh_technical_confirmation" in text


