def test_recommendation_diagnostics_samples_pass_now_with_technical_ignore():
    asof_date = pd.Timestamp("2026-05-01T00:00:00Z")
    action_rows = pd.DataFrame(
        [
            {
                "asof_date": asof_date,
                "symbol": "ABC",
                "action_code": "WATCH",
                "action_source": "watchlist",
                "execution_mode": "review_only",
                "reason_contract_status": "complete",
                "raw_context_json": "{}",
                "recommendation_reason_json": "{}",
                "load_ts": pd.Timestamp("2030-01-01T00:00:00Z"),
            }
        ]
    )
    candidate_rows = pd.DataFrame(
        [
            {
                "asof_date": asof_date,
                "symbol": "ABC",
                "setup_id": "DEFENSIVE_REGIME_POSITION_V1",
                "candidate_state": "PASS_NOW",
                "technical_state": "IGNORE",
                "technical_trigger_type": "missing",
                "rule_pass": True,
                "watch_enabled": True,
                "setup_score": 82.0,
                "technical_score": 0.0,
                "watch_reason_detail": "Aggregate score passed without entry trigger.",
                "load_ts": pd.Timestamp("2030-01-01T00:00:00Z"),
            }
        ]
    )

    payload = recommendation_diagnostics.summarize_recommendation_rows(
        action_rows,
        candidates=candidate_rows,
    )

    cause = payload["primary_no_buy_cause"]
    artifacts = payload["technical_artifacts"]
    samples = payload["upstream_candidates"]["pass_now_with_technical_ignore_samples"]
    assert cause["code"] == "upstream_pass_now_without_technical_confirmation"
    assert cause["evidence"]["pass_now_with_technical_ignore_count"] == 1
    assert cause["evidence"]["technical_entry_readiness_diagnosis"] == "aggregate_candidate_score_without_technical_entry_confirmation"
    assert cause["evidence"]["technical_artifacts"]["status"] == "current_pass_now_technical_ignore_conflict"
    assert artifacts["status"] == "current_pass_now_technical_ignore_conflict"
    assert artifacts["source_rows_precede_current_code"] is False
    assert artifacts["rerun_required_before_policy_tuning"] is False
    assert artifacts["safe_to_tune_technical_thresholds"] is False
    assert cause["evidence"]["samples"][0]["symbol"] == "ABC"
    assert samples[0]["setup_id"] == "DEFENSIVE_REGIME_POSITION_V1"
    assert samples[0]["final_action"] == "WATCH"
    assert cause["safe_to_tune_policy"] is False
    assert cause["next_commands"][0]["command"] == "python -m advisory.recommendation_diagnostics --format json"
    assert "Inspect current PASS_NOW technical-ignore samples" in cause["next_commands"][0]["purpose"]
    assert cause["next_commands"][1]["command"] == "./all_advisory.sh"
    assert any("Fresh PASS_NOW candidates still have technical_state=IGNORE" in step for step in payload["operator_next_steps"])
    assert any("inspect rule-engine scoring before running threshold calibration" in step for step in payload["operator_next_steps"])
    assert not any("stale pre-fix artifacts" in step for step in payload["operator_next_steps"])
    assert not any("run dry-run technical threshold calibration" in step for step in payload["operator_next_steps"])


