    assert freshness["source_rows_precede_current_code_by_source"]["action_recommendations"] is False
    assert freshness["source_rows_precede_current_code_by_source"]["candidates"] is True
    assert freshness["stale_code_components_by_source"]["action_recommendations"] == []
    assert freshness["stale_code_components_by_source"]["candidates"] == ["rule_engine"]


