def test_operator_health_context_gate_policy_surfaces_single_regime_gate(monkeypatch):
    monkeypatch.setenv("ACTION_MARKET_CONTEXT_REGIME_LABEL_HARD_BLOCK_ENABLED", "true")
    monkeypatch.delenv("RULE_ENGINE_REGIME_LABEL_HARD_BLOCK_ENABLED", raising=False)
    monkeypatch.delenv("RULE_ENGINE_OVERLAY_LABEL_HARD_BLOCK_ENABLED", raising=False)
    monkeypatch.delenv("ACTION_MARKET_CONTEXT_SCORE_RISK_OFF_HARD_BLOCK_ENABLED", raising=False)
    monkeypatch.delenv("ACTION_MARKET_CONTEXT_WEAK_BREADTH_HARD_BLOCK_ENABLED", raising=False)
    monkeypatch.delenv("ACTION_MARKET_CONTEXT_HIGH_MACRO_RISK_HARD_BLOCK_ENABLED", raising=False)
    monkeypatch.delenv("HYPOTHESIS_MARKET_CONTEXT_REGIME_LABEL_HARD_BLOCK_ENABLED", raising=False)
    monkeypatch.delenv("HYPOTHESIS_MARKET_CONTEXT_SCORE_RISK_OFF_HARD_BLOCK_ENABLED", raising=False)
    monkeypatch.delenv("HYPOTHESIS_MARKET_CONTEXT_WEAK_BREADTH_HARD_BLOCK_ENABLED", raising=False)
    monkeypatch.delenv("HYPOTHESIS_MARKET_CONTEXT_HIGH_MACRO_RISK_HARD_BLOCK_ENABLED", raising=False)

    section = operator_health.check_context_gate_policy()
    hints = operator_health.build_fix_hints({"context_gate_policy": section})
    trust = operator_health.build_trust_gate({"context_gate_policy": section})
    blockers = operator_health.build_current_blockers({"context_gate_policy": section}, hints, limit=10)

    assert section["status"] == "warn"
    assert section["active_single_regime_flags"] == ["ACTION_MARKET_CONTEXT_REGIME_LABEL_HARD_BLOCK_ENABLED"]
    assert section["global_regime_label_blocks_buy"] is True
    hint = next(row for row in hints if row["details"].get("section") == "context_gate_policy")
    assert "context_gate_policy_audit.py --fail-on-single-regime" in hint["commands"][0]
    trust_check = next(row for row in trust["checks"] if row["key"] == "context_gate_policy")
    assert trust_check["status"] == "warn"
    blocker = next(row for row in blockers["rows"] if row["details"].get("section") == "context_gate_policy")
    assert blocker["category"] == "advisory_trust"
    assert blocker["details"]["global_regime_label_blocks_buy"] is True


