def test_recommendation_diagnostics_primary_no_buy_cause_prioritizes_trust_before_suppressions():
    cause = recommendation_diagnostics.classify_primary_no_buy_cause(
        positive_count=0,
        suppression_counts={"feature_freshness_blocked": 10, "market_context_blocked": 3},
        upstream={
            "pass_now_with_technical_ignore_count": 2,
            "pass_now_with_technical_ignore_samples": [
                {
                    "symbol": "ABC",
                    "setup_id": "SETUP",
                    "candidate_state": "PASS_NOW",
                    "technical_state": "IGNORE",
                }
            ],
            "technical_entry_readiness": {
                "diagnosis": "aggregate_candidate_score_without_technical_entry_confirmation",
                "confirmed_entry_candidate_count": 0,
            },
        },
        handoff={"portfolio_technical_entry_not_confirmed_count": 1},
        diagnostic_trust={
            "status": "requires_advisory_rerun",
            "operator_action": "Rerun all_advisory.sh before interpreting the missing BUY state.",
            "reasons": ["source_rows_precede_current_code"],
            "stale_context_gate_conflict": True,
            "hard_context_gate_count": 7,
        },
        action_counts={"WATCH": 4},
    )

