    assert cause["evidence"]["pass_now_with_technical_ignore_count"] == 2
    assert cause["evidence"]["pass_now_with_technical_ignore_samples"][0]["symbol"] == "ABC"
    assert cause["evidence"]["technical_entry_readiness"]["diagnosis"] == "aggregate_candidate_score_without_technical_entry_confirmation"
    assert cause["safe_to_tune_policy"] is False
    assert [step["command"] for step in cause["next_commands"]] == [
        "./all_advisory.sh",
        "python -m advisory.recommendation_diagnostics --format text",
    ]
    assert "Rerun all_advisory.sh" in cause["operator_action"]


