def test_recommendation_diagnostics_infers_legacy_market_block_reason_from_context_labels():
    asof_date = pd.Timestamp("2026-05-01T00:00:00Z")
    rows = pd.DataFrame(
        [
            {
                "asof_date": asof_date,
                "symbol": "ABC",
                "setup_id": "SETUP",
                "action_code": "MANUAL_REVIEW",
                "action_source": "portfolio",
                "execution_mode": "review_only",
                "reason_contract_status": "complete",
                "action_reason": "Positive action blocked by market context.",
                "raw_context_json": json.dumps(
                    {
                        "market_context_adjustment": "positive_action_blocked_by_market_context",
                        "market_context_adjustment_json": {
                            "reason": "Legacy row without explicit risk_off_block_reason.",
                            "regime_name": "RISK_OFF",
                            "macro_risk_state": "HIGH",
                            "risk_off_score": 0.42,
                            "breadth_trend_alignment_pct": 45.0,
                            "regime_label_hard_block_enabled": False,
                            "score_risk_off_hard_block": False,
                        },
                    }
                ),
                "recommendation_reason_json": json.dumps(
                    {
                        "status": "complete",
                        "evidence": {
                            "macro_regime": {
                                "market_context_adjustment": "positive_action_blocked_by_market_context",
                                "regime_name": "RISK_OFF",
                                "macro_risk_state": "HIGH",
                                "risk_off_score": 0.42,
                                "breadth_trend_alignment_pct": 45.0,
                                "multi_context_diagnostics": {
                                    "macro_stress_context": {"label": "hard_macro_risk"},
                                    "breadth_context": {"label": "broad_participation_ok"},
                                    "technical_confirmation_context": {"label": "constructive"},
                                },
                            }
                        },
                    }
                ),
            }
        ]
    )

    payload = recommendation_diagnostics.summarize_recommendation_rows(rows)
