    assert payload["market_context_blocks"]["blocked_label_counts"]["technical"] == {"constructive": 1}
    assert block_sample["block_reason"] == "hard_macro_risk"
    assert block_sample["multi_context_labels"]["macro_stress"] == "hard_macro_risk"
    assert block_sample["block_reason_inferred"] is True
    assert block_sample["macro_hard_risk"] is True
    assert payload["suppression_counts"]["hard_macro_risk"] == 1


