def test_recommendation_diagnostics_threshold_research_plan_includes_trigger_near_miss_evidence(monkeypatch):
    columns = {"evaluated_at", "horizon_days", "archetype_breakdown_json"}

    def fake_sql_to_df(sql, *args, **kwargs):
        sql_text = str(sql)
        if "MAX(evaluated_at)" in sql_text:
            return pd.DataFrame({"latest_evaluated_at": [pd.Timestamp("2026-06-20T00:00:00Z")]})
        if "archetype_breakdown_json" in sql_text:
            payload = {
                "trigger_near_miss_breakdown": [
                    {
                        "near_miss_archetype": "breakout",
                        "near_miss_blocker_key": "breakout_volume_ratio",
                        "near_miss_blocker_codes": ["breakout_volume_ratio_below_min"],
                        "signal_count": 12,
                        "avg_return_after_cost": 0.052,
                        "hit_rate_after_cost": 0.58,
                    },
                    {
                        "near_miss_archetype": "pullback",
                        "near_miss_blocker_key": "support_hold",
                        "near_miss_blocker_codes": ["pullback_support_not_confirmed"],
                        "signal_count": 11,
                        "avg_return_after_cost": -0.012,
                        "hit_rate_after_cost": 0.31,
                    },
                ],
            }
            return pd.DataFrame(
                {
                    "evaluated_at": [pd.Timestamp("2026-06-20T00:00:00Z")],
                    "horizon_days": [10],
                    "archetype_breakdown_json": [json.dumps(payload)],
                }
            )
        raise AssertionError(f"unexpected query: {sql_text}")

    monkeypatch.setattr(recommendation_diagnostics, "_table_columns", lambda table_name: columns)
    monkeypatch.setattr(recommendation_diagnostics, "sql_to_df", fake_sql_to_df)

    plan = recommendation_diagnostics.build_technical_threshold_research_plan(
        candidate_source_availability={"candidate_lookup_asof_date": "2026-06-18T00:00:00+00:00"},
        technical_readiness={
            "positive_or_constructive_candidate_count": 7,
            "confirmed_entry_candidate_count": 0,
            "technical_trigger_blockers": {"status": "trigger_blocker_contract_available"},
            "buy_readiness_blockers": {"status": "buy_readiness_contract_available"},
        },
    )

    research = plan["trigger_near_miss_research"]
    assert research["status"] == "ok"
    assert plan["trigger_near_miss_candidate_count"] == 1
    assert plan["trigger_near_miss_do_not_relax_count"] == 1
    assert research["top_relaxation_candidates"][0]["near_miss_blocker_key"] == "breakout_volume_ratio"
    assert research["top_do_not_relax"][0]["near_miss_blocker_key"] == "support_hold"
    assert research["broker_execution_allowed"] is False
    assert research["policy_auto_promotion_allowed"] is False
    assert research["policy_effect"] == "diagnostic_only_no_threshold_change"


