def test_action_recommender_context_overlay_summary_suppresses_harmful_sector_split():
    rows = pd.DataFrame(
        [
            {
                "symbol": "MIDCAP",
                "context_asof_date": pd.Timestamp("2026-05-01T00:00:00Z"),
                "context_source": "announcement_context",
                "overlay_id": "ann-1",
                "direction": "positive",
                "pressure_score": 0.8,
                "context_class": "ORDER_WIN",
                "sector_name": "Pharmaceuticals",
                "reason": "Order win looks positive but sector split is harmful/no-lift.",
            },
            {
                "symbol": "MIDCAP",
                "context_asof_date": pd.Timestamp("2026-04-30T00:00:00Z"),
                "context_source": "announcement_context",
                "overlay_id": "ann-2",
                "direction": "positive",
                "pressure_score": 0.7,
                "context_class": "ORDER_WIN",
                "sector_name": "Capital Goods",
                "reason": "Order win is supported in this sector split.",
            },
        ]
    )
    reliability = {
        "status": "ok",
        "families": {
            "announcement_context": {
                "classification": "candidate_helpful",
                "runtime_policy_contract": {
                    "allowed_runtime_uses": {"watch_priority": True, "de_risk_review": False, "broker_execution": False},
                },
                "context_class_diagnostics": [
                    {"context_class": "ORDER_WIN", "classification": "candidate_helpful"},
                ],
                "sector_diagnostics": [
                    {"sector_name": "Pharmaceuticals", "classification": "hurts_or_no_lift"},
                    {"sector_name": "Capital Goods", "classification": "candidate_helpful"},
                ],
            }
        },
    }

    summary_by_symbol = action_recommender._summarize_action_context_overlays(rows, source_family_reliability=reliability)
    summary = summary_by_symbol["MIDCAP"]
    alignment = action_recommender._context_overlay_action_alignment("BUY", summary)

    assert summary["positive_count"] == 2
    assert summary["effective_positive_count"] == 1
    assert summary["reliability_suppressed_count"] == 1
    assert summary["context_sector_reliability_counts"]["hurts_or_no_lift"] == 1
    assert summary["context_sector_reliability_counts"]["candidate_helpful"] == 1
    assert summary["top_overlays"][0]["sector_name"] == "Capital Goods"
    assert summary["top_overlays"][0]["context_sector_reliability"]["classification"] == "candidate_helpful"
    assert summary["top_suppressed_overlays"][0]["sector_name"] == "Pharmaceuticals"
    assert summary["top_suppressed_overlays"][0]["context_sector_reliability"]["classification"] == "hurts_or_no_lift"
    assert alignment["supportive_context_count"] == 1
    assert alignment["reliability_suppressed_context_count"] == 1
    assert alignment["top_supporting_overlays"][0]["context_sector_reliability"]["classification"] == "candidate_helpful"


