def test_event_policy_deterministic_fallback_tolerates_malformed_stored_json(monkeypatch):
    events = []
    monkeypatch.setattr(event_policy, "record_local_fallback_event", lambda **kwargs: events.append(kwargs) or kwargs)
    row = event_policy.build_policy_for_event(
        pd.Series(
            {
                "published_on": pd.Timestamp("2026-05-01T09:30:00Z"),
                "asof_date": pd.Timestamp("2026-05-01T00:00:00Z"),
                "setup_id": "EVENT_OPPORTUNITY_V1",
                "symbol": "ABC",
                "unique_id": "ABC-malformed-json-fallback",
                "event_class": "REGULATORY_NOTICE",
                "verdict": "review_manual",
                "setup_effect": "weakens",
                "materiality": "low",
                "score_impact": -0.02,
                "confidence": 0.4,
                "what_happened": "Company received a minor regulatory query with unclear impact.",
                "rationale": "Negative but likely immaterial.",
            }
        )
    )
    row["actionability_json"] = "{bad-actionability"
    row["raw_context_json"] = "{bad-raw-context"

    out = event_policy.apply_llm_manual_review(row, use_llm=False)
    notes = json.loads(out["operator_notes_json"])
    raw_context = json.loads(out["raw_context_json"])

    assert out["action_type"] == "REDUCE_EXPOSURE_REVIEW"
    assert out["action_status"] == "deterministic_reclassified_derisk_overlay"
    assert notes["final_action_type"] == "REDUCE_EXPOSURE_REVIEW"
    assert raw_context["operator_notes"]["authority_contract"]["broker_execution_allowed"] is False
    assert {
        event["source"]
        for event in events
        if event["fallback_type"] == "event_policy_json_parse_failed"
    } == {
        "event_policy_manual_review_actionability_json",
        "event_policy_manual_review_raw_context_json",
        "event_policy_manual_review_output_raw_context_json",
    }


