def test_event_policy_evaluator_ensure_tables_continues_additive_migration_after_base_checksum_drift(monkeypatch):
    calls = []
    events = []

    def fake_apply_schema_migration(**kwargs):
        calls.append(kwargs)
        if kwargs["migration_id"] == event_policy_evaluator.EVENT_POLICY_EVAL_SCHEMA_MIGRATION_ID:
            raise ValueError(
                "Migration checksum mismatch for "
                f"{event_policy_evaluator.EVENT_POLICY_EVAL_SCHEMA_MIGRATION_ID}: existing=old new=new"
            )
        return {"status": "applied"}

    monkeypatch.setattr(event_policy_evaluator, "apply_schema_migration", fake_apply_schema_migration)
    monkeypatch.setattr(event_policy_evaluator, "table_columns", lambda table_name: {"evaluated_at"} if table_name in {event_policy_evaluator.EVALUATIONS_TABLE, event_policy_evaluator.SUMMARY_TABLE} else set())
    monkeypatch.setattr(event_policy_evaluator, "record_local_fallback_event", lambda **kwargs: events.append(kwargs) or kwargs)

    event_policy_evaluator.ensure_tables()

    assert [call["migration_id"] for call in calls] == [
        event_policy_evaluator.EVENT_POLICY_EVAL_SCHEMA_MIGRATION_ID,
        event_policy_evaluator.EVENT_POLICY_EVAL_BENCHMARK_SCHEMA_MIGRATION_ID,
    ]
    assert events[0]["fallback_type"] == "event_policy_evaluator_base_schema_checksum_mismatch_ignored"
    assert events[0]["severity"] == "warn"
    assert events[0]["metadata"]["authority_scope"] == "research_only_schema_maintenance"


