def test_operator_health_ts_forecast_paper_missing_table_surfaces_fix_hint(monkeypatch):
    monkeypatch.setattr(operator_health, "table_exists", lambda table_name: False)

    section = operator_health.check_ts_forecast_paper_portfolio()
    hints = operator_health.build_fix_hints({"ts_forecast_paper": section})
    trust = operator_health.build_trust_gate({"ts_forecast_paper": section})
    blockers = operator_health.build_current_blockers({"ts_forecast_paper": section}, hints, limit=10)

    assert section["status"] == "warn"
    assert section["usable"] is False
    assert section["reasons"] == ["missing_ts_forecast_paper_table"]
