    assert section["policy_auto_promotion_allowed"] is False
    hint = next(row for row in hints if row["title"] == "TS forecast paper-portfolio evidence is missing or not matured")
    commands = " ".join(hint["commands"])
    assert "advisory.ts_forecast_paper_portfolio" in commands
    assert "advisory.ts_forecast_promotion_check" in commands
    assert hint["details"]["broker_execution_allowed"] is False
    assert hint["details"]["policy_auto_promotion_allowed"] is False
