def test_causal_event_memory_merges_duplicate_overlay_rows():
    overlays = {
        "announcement_context": pd.DataFrame(
            [
                {
                    "asof_date": "2026-06-18",
                    "observed_at": "2026-06-18T09:30:00Z",
                    "overlay_id": "ann-1",
                    "symbol": "ABC",
                    "event_type": "ORDER_WIN",
                    "context_class": "ORDER_WIN",
                    "direction": "positive",
                    "pressure_score": 0.4,
                    "authority_scope": "watchlist_pressure_only",
                },
                {
                    "asof_date": "2026-06-18",
                    "observed_at": "2026-06-18T10:30:00Z",
                    "overlay_id": "ann-2",
                    "symbol": "ABC",
                    "event_type": "ORDER_WIN",
                    "context_class": "ORDER_WIN",
                    "direction": "positive",
                    "pressure_score": 0.35,
                    "authority_scope": "watchlist_pressure_only",
                },
            ]
        )
    }

    memory = causal_event_memory.build_causal_event_memory_from_overlays(
        overlays,
        asof_date=pd.Timestamp("2026-06-18", tz="UTC"),
    )

    assert len(memory) == 1
    row = memory.iloc[0]
    assert row["symbol"] == "ABC"
    assert row["event_count"] == 2
    assert row["event_state"] == "positive_watch_pressure"
    assert bool(row["broker_execution_allowed"]) is False
    assert row["portfolio_authority"] == "none"
    refs = json.loads(row["source_refs_json"])
    assert {ref["overlay_id"] for ref in refs} == {"ann-1", "ann-2"}


