    assert preview_calls[0]["classification"] == "hurts_or_no_lift"
    assert preview_calls[0]["context_class"] == "dividend"
    assert preview_calls[1]["classification"] == "benchmark_beta_not_memory_alpha"
    assert preview_calls[1]["context_class"] == "order_win"


