def test_causal_event_provenance_json_dump_converts_nan_and_nat_to_null():
    payload = {
        "score": float("nan"),
        "timestamp": pd.NaT,
        "nested": {"value": pd.Timestamp("2026-06-21T00:00:00Z")},
    }

    serialized = causal_event_provenance._json_dumps(payload)

    assert "NaN" not in serialized
    assert "NaT" not in serialized
    parsed = json.loads(serialized)
    assert parsed["score"] is None
    assert parsed["timestamp"] is None
    assert parsed["nested"]["value"] == "2026-06-21T00:00:00+00:00"


