    assert tensor["event_type"] == "GUIDANCE_UPGRADE"
    assert tensor["affected_sectors"] == ["pharma"]
    assert tensor["affected_peers"] == ["SUNPHARMA", "CIPLA"]
    assert tensor["validated_affected_peers"] == ["SUNPHARMA"]
    assert tensor["unresolved_affected_peers"] == ["CIPLA"]
    assert tensor["affected_peer_identity_validation"]["status"] == "requires_identity_validation"
    assert tensor["affected_peer_identity_validation"]["broker_execution_allowed"] is False
    assert tensor["state_transition_hint"] == "UPGRADE_TO_PASS_NOW"


