    monkeypatch.setattr(llm_event_evaluator, "record_local_fallback_event", lambda **kwargs: fallback_events.append(kwargs) or kwargs)
    monkeypatch.setattr(llm_event_evaluator.AdvisoryEventEvaluator, "evaluate_payload", fake_evaluate)

    evaluations, risks, meta = llm_event_evaluator.build_outputs(events, model="test-model")

    assert len(evaluations) == 2
    assert risks.empty
    assert meta["compact_context_count"] == 1
    assert meta["raw_fallback_context_count"] == 1
    assert requested_raw_ids == ["raw-1"]
    assert fallback_events[0]["fallback_type"] == "llm_event_compact_announcement_evidence_missing_raw_fallback"
    assert fallback_events[0]["source"] == llm_event_evaluator.ANNOUNCEMENT_EVIDENCE_TABLE
    assert fallback_events[0]["metadata"]["compact_context_count"] == 1
    assert fallback_events[0]["metadata"]["raw_fallback_requested_count"] == 1
    assert fallback_events[0]["metadata"]["raw_fallback_loaded_count"] == 1
    assert fallback_events[0]["metadata"]["missing_raw_document_count"] == 0
    assert fallback_events[0]["metadata"]["raw_fallback_unique_id_sample"] == ["raw-1"]
    assert payloads[0]["document_context"]["context_source"] == "compact_announcement_evidence"
    assert payloads[0]["document_context"]["fallback_used"] is False
    assert payloads[0]["document_context"]["announcement_storage_form"] == "structured_event_plus_summary"
    assert payloads[0]["document_context"]["llm_evidence_mode"] == "event_tensor_plus_summary"
    assert payloads[0]["document_context"]["llm_review_ready"] is True
    assert payloads[0]["document_context"]["document_summary_text"] == compact_docs.iloc[0]["evidence_summary"]
    assert payloads[0]["document_context"]["document_text_excerpt"] == compact_docs.iloc[0]["evidence_excerpt"]
    assert payloads[1]["document_context"]["context_source"] == "raw_announcement_document_fallback"
