def test_download_runner_stops_on_failure_when_continue_disabled(monkeypatch):
    monkeypatch.setattr(
        download_runner,
        "DOWNLOAD_STEPS",
        [
            {"module": "mod.ok", "args": [], "purpose": "test"},
            {"module": "mod.fail", "args": [], "purpose": "test"},
            {"module": "mod.skip", "args": [], "purpose": "test"},
        ],
    )

    def fake_run(step: dict[str, object]) -> dict[str, object]:
        if step["module"] == "mod.fail":
            return {"module": step["module"], "status": "failed", "returncode": 1}
        return {"module": step["module"], "status": "ok", "returncode": 0}

    monkeypatch.setattr(download_runner, "run_download_module", fake_run)

    payload = download_runner.run_all_downloads(continue_on_error=False, dry_run=False)
    assert payload["status"] == "failed"
    assert [row["module"] for row in payload["results"]] == ["mod.ok", "mod.fail"]


def test_download_runner_classifies_standard_run_statuses():
    assert download_runner.classify_run_status(status="ok", module_name="data.fred.us_macro", returncode=0) == "ok"
    assert download_runner.classify_run_status(status="failed", module_name="data.dhanlive.ohlcv", error="DhanAPIError: status 401 token expired") == "auth_unavailable"
    assert (
        download_runner.classify_run_status(
            status="failed",
            module_name="data.dhanlive.ohlcv",
            error="ValueError: No Dhan security id mapped for NSE:HUIL",
        )
        == "reference_mapping_missing"
    )
    assert (
        download_runner.classify_run_status(
            status="failed",
            module_name="advisory.data_sync",
            error="No match in Dhan master for symbol ABC",
        )
        == "reference_mapping_missing"
    )
    assert download_runner.classify_run_status(status="failed", module_name="data.nseindia.recent_events", error="ReadTimeout: nseindia timed out") == "source_unavailable"
    assert download_runner.classify_run_status(status="failed", module_name="data.nseindia.bhavcopy_parser", error="ValueError: schema changed") == "parse_failed"
    assert download_runner.classify_run_status(status="failed", module_name="data.nsdl.fpi", error="No data for date") == "no_data"


def test_download_runner_refines_successful_zero_row_run_state():
    no_data = download_runner.build_run_state_result(
        {
            "module": "data.mospi.cpi",
            "status": "ok",
            "returncode": 0,
            "rows": 0,
            "no_data_count": 1,
            "state_advanced": False,
        },
        step={"module": "data.mospi.cpi", "args": [], "purpose": "macro"},
    )
    unavailable = download_runner.build_run_state_result(
        {
            "module": "data.nseindia.recent_events",
            "status": "ok",
            "returncode": 0,
            "rows": 0,
            "source_unavailable_count": 1,
            "state_advanced": False,
        },
        step={"module": "data.nseindia.recent_events", "args": [], "purpose": "events"},
    )
    reference_missing = download_runner.build_run_state_result(
        {
            "module": "data.dhanlive.ohlcv",
            "status": "ok",
            "returncode": 0,
            "rows": 0,
            "reference_mapping_missing_count": 1,
            "state_advanced": False,
        },
        step={"module": "data.dhanlive.ohlcv", "args": [], "purpose": "dhan_ohlcv_precheck"},
    )
    auth_missing = download_runner.build_run_state_result(
        {
            "module": "data.screenerin.screener_parser",
            "status": "ok",
            "returncode": 0,
            "rows": 0,
            "auth_unavailable_count": 1,
            "no_data_count": 1,
            "state_advanced": False,
        },
        step={"module": "data.screenerin.screener_parser", "args": [], "purpose": "screener_sync_registered"},
    )
    parse_failed = download_runner.build_run_state_result(
        {
            "module": "data.nseindia.bhavcopy_parser",
            "status": "ok",
            "returncode": 0,
            "rows": 0,
            "classification_counts": {"parse_failed": 1, "no_data": 1},
            "state_advanced": False,
        },
        step={"module": "data.nseindia.bhavcopy_parser", "args": [], "purpose": "market_wide"},
    )
    explicit = download_runner.build_run_state_result(
        {
            "module": "data.nseindia.recent_events",
            "status": "ok",
            "returncode": 0,
            "rows": 0,
            "classification": "auth_unavailable",
            "state_advanced": False,
        },
        step={"module": "data.nseindia.recent_events", "args": [], "purpose": "events"},
    )

    assert no_data["classification"] == "no_data"
    assert no_data["state_advanced"] is False
    assert unavailable["classification"] == "source_unavailable"
    assert unavailable["state_advanced"] is False
    assert reference_missing["classification"] == "reference_mapping_missing"
    assert reference_missing["state_advanced"] is False
    assert auth_missing["classification"] == "auth_unavailable"
    assert auth_missing["auth_unavailable_count"] == 1
    assert auth_missing["state_advanced"] is False
    assert parse_failed["classification"] == "parse_failed"
    assert parse_failed["classification_counts"] == {"parse_failed": 1, "no_data": 1}
    assert parse_failed["state_advanced"] is False
    assert explicit["classification"] == "auth_unavailable"


