def test_technical_features_rebuild_cleanup_uses_retryable_operation(monkeypatch):
    operation_names: list[str] = []
    executed: list[tuple[str, object]] = []
    upserts: list[tuple[str, int]] = []

    class FakeCursor:
        def execute(self, query, params=None):
            executed.append((str(query), params))

    class FakeSession:
        def __enter__(self):
            return None, FakeCursor()

        def __exit__(self, *_args):
            return False

    def fake_execute_db_operation(operation, *, operation_name, **_kwargs):
        operation_names.append(operation_name)
        return operation()

    frame = pd.DataFrame(
        [
            {
                "asof_date": pd.Timestamp("2026-06-10T00:00:00Z"),
                "symbol": "ABC",
                "series": "EQ",
                "close": 100.0,
            }
        ]
    )
    monkeypatch.setattr(technical_features, "db_session", lambda: FakeSession())
    monkeypatch.setattr(technical_features, "execute_db_operation", fake_execute_db_operation)
    monkeypatch.setattr(
        technical_features,
        "upsert_to_db",
        lambda frame, table, **_kwargs: upserts.append((table, len(frame))),
    )

    technical_features.persist_technical_features(frame, rebuild=True, symbols=["ABC"])

    assert operation_names == ["technical_features:delete_rebuild_features"]
    assert len(executed) == 1
    assert f"DELETE FROM {technical_features.TABLE_NAME}" in executed[0][0]
    assert executed[0][1] == (["ABC"],)
    assert upserts == [(technical_features.TABLE_NAME, 1)]


def test_technical_features_builds_refresh_status_rows_from_sync_and_feature_output():
    data_sync_result = {
        "ohlcv": [
            {"symbol": "ABC", "action": "sync", "rows": 2, "reason": "ohlcv_missing_or_stale"},
            {
                "symbol": "XYZ",
                "action": "issue",
                "reason": "dhan_daily_sync_failed",
                "error_type": "DhanAPIError",
                "error": "bad values",
            },
        ],
        "fundamentals": [{"symbol": "ABC", "action": "skip", "reason": "fundamentals_present"}],
    }
    feature_df = pd.DataFrame(
        [
            {"symbol": "ABC", "asof_date": pd.Timestamp("2026-06-19T00:00:00Z")},
        ]
    )

    rows = technical_features.build_refresh_status_rows(
        symbols=["ABC", "XYZ"],
        asof_date=pd.Timestamp("2026-06-19T00:00:00Z"),
        data_sync_result=data_sync_result,
        feature_df=feature_df,
    )

    by_key = {(row["symbol"], row["stage"]): row for row in rows.to_dict(orient="records")}
    assert by_key[("ABC", "ohlcv")]["status"] == "ok"
    assert by_key[("XYZ", "ohlcv")]["status"] == "issue"
    assert by_key[("XYZ", "ohlcv")]["error_type"] == "DhanAPIError"
    assert by_key[("ABC", "technical_build")]["status"] == "ok"
    assert by_key[("XYZ", "technical_build")]["status"] == "issue"
    assert by_key[("XYZ", "technical_build")]["reason"] == "technical_rows_missing_after_ohlcv_issue"


