def test_news_overlay_engine_rebuild_cleanup_uses_retryable_operation(monkeypatch):
    operation_names: list[str] = []
    executed: list[tuple[str, object]] = []
    upserts: list[tuple[str, int]] = []

    class FakeCursor:
        def execute(self, query, params=None):
            executed.append((str(query), params))

    class FakeSession:
        def __enter__(self):
            return None, FakeCursor()

        def __exit__(self, *_args):
            return False

    def fake_execute_db_operation(operation, *, operation_name, **_kwargs):
        operation_names.append(operation_name)
        return operation()

    frame = pd.DataFrame(
        [
            {
                "asof_date": pd.Timestamp("2026-06-10T00:00:00Z"),
                "base_regime": "STABLE",
                "overlay_name": "NONE",
                "overlay_intensity": 0.0,
                "overlay_reason": "no dominant overlay signals",
                "source_count": 0,
                "load_ts": pd.Timestamp("2026-06-10T10:00:00Z"),
            }
        ]
    )
    monkeypatch.setattr(news_overlay_engine, "ensure_output_table", lambda: None)
    monkeypatch.setattr(news_overlay_engine, "db_session", lambda: FakeSession())
    monkeypatch.setattr(news_overlay_engine, "execute_db_operation", fake_execute_db_operation)
    monkeypatch.setattr(
        news_overlay_engine,
        "upsert_to_db",
        lambda frame, table, **_kwargs: upserts.append((table, len(frame))),
    )

    news_overlay_engine.persist_overlay_state(
        frame,
        rebuild=True,
        asof_date=pd.Timestamp("2026-06-10T00:00:00Z"),
    )

    assert operation_names == ["news_overlay_engine:delete_rebuild_overlay"]
    assert len(executed) == 1
    assert f"DELETE FROM {news_overlay_engine.TABLE_NAME}" in executed[0][0]
    assert upserts == [(news_overlay_engine.TABLE_NAME, 1)]


def test_rule_engine_resolves_overlay_screeners_and_softens_blocked_overlay_by_default(monkeypatch):
    monkeypatch.delenv(rule_engine.RULE_ENGINE_OVERLAY_LABEL_HARD_BLOCK_ENABLED_ENV, raising=False)
    setup = {
        "setup_id": "TEST",
        "screeners": ["screen-a", "screen-b"],
        "screener_mode": "union",
        "allowed_regimes": ["STABLE"],
        "allowed_overlays": ["NONE"],
        "blocked_overlays": ["GEOPOLITICAL_RISK"],
        "overlay_screeners": {
            "TARIFF_PRESSURE": {"add": ["screen-c"], "remove": ["screen-a"]},
        },
        "score_thresholds": {"pass_now": 0.68, "watch_breakout": 0.58, "watch_event": 0.48, "near_miss_gap": 0.05},
    }
    active_screeners, mode, theme_ids = rule_engine.resolve_setup_screeners(setup, "TARIFF_PRESSURE")
    assert active_screeners == ["screen-b", "screen-c"]
    assert mode == "union"
    assert theme_ids == []

    row = pd.Series(
        {
            "company_master_id": "nse:ABC",
            "adj_close": 100.0,
            "fundamentals_freshness_status": "fresh",
            "market_cap": 100000.0,
            "avg_traded_value_20d": 1000000000.0,
            "breakout_extension_pct": 1.0,
            "pass_above_dma_20": True,
            "pass_above_dma_50": True,
            "pass_above_dma_200": True,
            "rs_vs_benchmark": 0.1,
            "rs_vs_sector": 0.1,
        }
    )
    candidate_state, details, rejections = rule_engine.evaluate_setup_row(
        row,
        regime_name="STABLE",
        overlay_name="GEOPOLITICAL_RISK",
        setup=setup,
    )
    assert candidate_state != "REJECT"
    assert "overlay:geopolitical_risk_blocked_context_only" in details["soft_failures"]
    assert any(item["reason_code"] == "overlay_blocked_context_only" and item["severity"] == "soft" for item in rejections)
    assert all(item["reason_code"] != "overlay_not_allowed" for item in rejections)


