def test_llm_payload_includes_bounded_exchange_context(monkeypatch):
    event_row = pd.Series(
        {
            "published_on": pd.Timestamp("2026-04-01T09:00:00Z"),
            "asof_date": pd.Timestamp("2026-04-01T00:00:00Z"),
            "setup_id": "TEST",
            "setup_name": "Test",
            "unique_id": "u1",
            "event_source": "announcement",
            "company_master_id": "nse:HDFCBANK",
            "symbol": "HDFCBANK",
            "exchange": "NSE",
            "source_url": "",
            "subject": "Order win",
            "filed_under_category": "General",
            "parse_status": "parsed",
            "concise_summary_text": "Won order",
            "categories_json": "[]",
            "watch_reasons_json": "[]",
        }
    )
    monkeypatch.setattr(llm_event_evaluator, "load_point_in_time_context", lambda *args, **kwargs: {"regime_name": "STABLE"})
    monkeypatch.setattr(
        llm_event_evaluator,
        "load_exchange_context",
        lambda *args, **kwargs: {
            "context_contract": {
                "authority_scope": "structured_context_only",
                "action_policy_effect": "llm_classification_support_only",
                "portfolio_authority": "none",
                "broker_execution_allowed": False,
                "lookback_days": 30,
                "max_events": 8,
                "bounded_event_rows": True,
            },
            "context_summary": {
                "feature_context_available": True,
                "recent_event_count": 1,
                "recent_event_limit": 8,
                "lookback_days": 30,
            },
            "features": {"exchange_distribution_score": 0.4},
            "recent_events": [{"event_source": "nse_bulk_deal", "side": "SELL"}],
        },
    )
    monkeypatch.setattr(
        llm_event_evaluator,
        "load_latest_market_context",
        lambda *args, **kwargs: {
            "summary": {"regime_name": "RISK_OFF", "breadth_trend_alignment_pct": 32.0},
            "top_universe": [{"symbol": "HDFCBANK", "rank_pct": 2.0}],
        },
    )
    payload = llm_event_evaluator.build_payload(event_row, None)
    assert payload["authority_contract"]["authority_scope"] == "llm_event_classification_only"
    assert payload["authority_contract"]["broker_execution_allowed"] is False
    assert payload["authority_contract"]["requires_downstream_policy_gate"] is True
    assert payload["exchange_context"]["context_contract"]["broker_execution_allowed"] is False
    assert payload["exchange_context"]["context_contract"]["bounded_event_rows"] is True
    assert payload["exchange_context"]["context_summary"]["recent_event_limit"] == 8
    assert payload["exchange_context"]["features"]["exchange_distribution_score"] == 0.4
    assert len(payload["exchange_context"]["recent_events"]) == 1
    assert payload["broad_market_context"]["summary"]["regime_name"] == "RISK_OFF"
    assert payload["broad_market_context"]["symbol_context"]["rank_pct"] == 2.0


