def test_adversarial_review_evaluator_labels_false_positive_and_avoided_loss():
    dataset = pd.DataFrame(
        [
            {
                "published_on": pd.Timestamp("2026-04-01T09:00:00Z"),
                "asof_date": pd.Timestamp("2026-04-01T00:00:00Z"),
                "setup_id": "S1",
                "symbol": "ABC",
                "unique_id": "u1",
                "event_source": "announcement",
                "review_action": "veto",
                "review_score": -0.45,
                "veto": True,
                "review_reason": "high_contradiction",
                "review_flags_json": json.dumps(["high_contradiction"]),
                "forward_return_h5": -0.05,
                "entry_date_h5": pd.Timestamp("2026-04-02T00:00:00Z"),
                "exit_date_h5": pd.Timestamp("2026-04-08T00:00:00Z"),
                "entry_close_h5": 100.0,
                "exit_close_h5": 95.0,
                "benchmark_name": "NIFTY 50",
                "benchmark_entry_date_h5": pd.Timestamp("2026-04-02T00:00:00Z"),
                "benchmark_exit_date_h5": pd.Timestamp("2026-04-08T00:00:00Z"),
                "benchmark_entry_close_h5": 1000.0,
                "benchmark_exit_close_h5": 1010.0,
                "benchmark_forward_return_h5": 0.01,
            },
            {
                "published_on": pd.Timestamp("2026-04-01T09:00:00Z"),
                "asof_date": pd.Timestamp("2026-04-01T00:00:00Z"),
                "setup_id": "S1",
                "symbol": "XYZ",
                "unique_id": "u2",
                "event_source": "announcement",
                "review_action": "veto",
                "review_score": -0.45,
                "veto": True,
                "review_reason": "high_contradiction",
                "review_flags_json": json.dumps(["high_contradiction"]),
                "forward_return_h5": 0.08,
                "entry_date_h5": pd.Timestamp("2026-04-02T00:00:00Z"),
                "exit_date_h5": pd.Timestamp("2026-04-08T00:00:00Z"),
                "entry_close_h5": 100.0,
                "exit_close_h5": 108.0,
                "benchmark_name": "NIFTY 50",
                "benchmark_entry_date_h5": pd.Timestamp("2026-04-02T00:00:00Z"),
                "benchmark_exit_date_h5": pd.Timestamp("2026-04-08T00:00:00Z"),
                "benchmark_entry_close_h5": 1000.0,
                "benchmark_exit_close_h5": 1010.0,
                "benchmark_forward_return_h5": 0.01,
            },
        ]
    )

    out = adversarial_review_evaluator.build_evaluation_rows(
        dataset,
        horizons=[5],
        cost_bps=25.0,
        false_positive_return_threshold=0.03,
        evaluated_at=pd.Timestamp("2026-04-20T00:00:00Z"),
    ).sort_values("symbol")

    abc = out[out["symbol"] == "ABC"].iloc[0]
    xyz = out[out["symbol"] == "XYZ"].iloc[0]
    assert round(float(abc["forward_return_after_cost"]), 4) == -0.0525
    assert round(float(abc["avoided_loss_return_after_cost"]), 4) == 0.0525
    assert round(float(abc["excess_avoided_loss_return_after_cost"]), 4) == 0.0575
    assert bool(abc["would_have_been_false_positive"]) is False
    assert bool(abc["would_have_been_excess_false_positive"]) is False
    assert round(float(xyz["forward_return_after_cost"]), 4) == 0.0775
    assert round(float(xyz["avoided_loss_return_after_cost"]), 4) == -0.0775
    assert round(float(xyz["excess_avoided_loss_return_after_cost"]), 4) == -0.0725
    assert bool(xyz["would_have_been_false_positive"]) is True
    assert bool(xyz["would_have_been_excess_false_positive"]) is True
    assert json.loads(abc["raw_context_json"])["authority_scope"] == "research_only_no_policy_change"


def test_adversarial_review_evaluator_summarizes_veto_false_positive_rate():
    evaluated_at = pd.Timestamp("2026-04-20T00:00:00Z")
    evaluations = pd.DataFrame(
        [
            {
                "evaluated_at": evaluated_at,
                "horizon_days": 5,
                "asof_date": pd.Timestamp("2026-04-01T00:00:00Z"),
                "review_action": "veto",
                "review_score": -0.5,
                "veto": True,
                "review_flags_json": json.dumps(["high_contradiction"]),
                "benchmark_forward_return": 0.00,
                "forward_return_after_cost": -0.06,
                "avoided_loss_return_after_cost": 0.06,
                "excess_avoided_loss_return_after_cost": 0.06,
                "would_have_been_false_positive": False,
                "would_have_been_excess_false_positive": False,
                "matured": True,
            },
            {
                "evaluated_at": evaluated_at,
                "horizon_days": 5,
                "asof_date": pd.Timestamp("2026-04-02T00:00:00Z"),
                "review_action": "veto",
                "review_score": -0.4,
                "veto": True,
                "review_flags_json": json.dumps(["high_contradiction"]),
                "benchmark_forward_return": 0.00,
                "forward_return_after_cost": -0.02,
                "avoided_loss_return_after_cost": 0.02,
                "excess_avoided_loss_return_after_cost": 0.02,
                "would_have_been_false_positive": False,
                "would_have_been_excess_false_positive": False,
                "matured": True,
            },
            {
                "evaluated_at": evaluated_at,
                "horizon_days": 5,
                "asof_date": pd.Timestamp("2026-04-03T00:00:00Z"),
                "review_action": "veto",
                "review_score": -0.4,
                "veto": True,
                "review_flags_json": json.dumps(["high_contradiction"]),
                "benchmark_forward_return": 0.00,
                "forward_return_after_cost": 0.07,
                "avoided_loss_return_after_cost": -0.07,
                "excess_avoided_loss_return_after_cost": -0.07,
                "would_have_been_false_positive": True,
                "would_have_been_excess_false_positive": True,
                "matured": True,
            },
            {
                "evaluated_at": evaluated_at,
                "horizon_days": 5,
                "asof_date": pd.Timestamp("2026-04-04T00:00:00Z"),
                "review_action": "clear",
                "review_score": 0.0,
                "veto": False,
                "review_flags_json": json.dumps([]),
                "benchmark_forward_return": 0.00,
                "forward_return_after_cost": 0.08,
                "avoided_loss_return_after_cost": -0.08,
                "excess_avoided_loss_return_after_cost": -0.08,
                "would_have_been_false_positive": True,
                "would_have_been_excess_false_positive": True,
                "matured": True,
            },
        ]
    )
    evaluations = adversarial_review_evaluator.normalize_evaluation_frame(evaluations)

    summary = adversarial_review_evaluator.summarize_evaluations(
        evaluations,
        evaluated_at=evaluated_at,
        min_matured_rows=3,
    )

    veto = summary[(summary["group_type"] == "review_action") & (summary["group_value"] == "veto")].iloc[0]
    assert int(veto["matured_count"]) == 3
    assert round(float(veto["false_positive_rate"]), 4) == 0.3333
    assert round(float(veto["excess_false_positive_rate"]), 4) == 0.3333
    assert round(float(veto["avg_excess_avoided_loss_return_after_cost"]), 4) == 0.0033
    assert veto["recommendation"] == "candidate_veto_policy_keep_or_tighten"
    flag = summary[(summary["group_type"] == "review_flag") & (summary["group_value"] == "high_contradiction")].iloc[0]
    assert int(flag["matured_count"]) == 3
    clear = summary[(summary["group_type"] == "review_action") & (summary["group_value"] == "clear")].iloc[0]
    assert clear["recommendation"] == "baseline_clear_not_adversarial_intervention"


