def test_adversarial_review_evaluator_ensure_tables_uses_schema_registry(monkeypatch):
    calls = []
    monkeypatch.setattr(adversarial_review_evaluator, "apply_schema_migration", lambda **kwargs: calls.append(kwargs) or {"status": "applied"})

