def test_model_training_runner_builds_signal_quality_research_commands():
    args = argparse.Namespace(
        signal_quality_horizons=[5, 10],
        cost_bps=12.5,
        return_threshold=0.04,
        from_date="2026-01-01",
        to_date="2026-05-01",
        signal_quality_window_days=180,
        signal_quality_step_days=90,
        signal_quality_windows=4,
        signal_quality_min_matured_rows=20,
        signal_quality_min_stable_windows=2,
        signal_quality_min_stable_window_rate=0.5,
        include_signal_quality_split_reports=True,
        signal_quality_split_report_min_matured_rows=11,
        signal_quality_split_report_top_n=7,
        negative_pressure_min_matured_rows=9,
        context_watch_min_matured_rows=8,
        action_transition_min_matured_rows=7,
        action_evidence_provenance_limit=111,
        causal_event_memory_min_matured_rows=6,
        causal_event_memory_limit_per_source=123,
        generate_causal_event_memory_config_previews=True,
        include_causal_event_memory_suppression_previews=True,
        max_causal_event_memory_config_previews=2,
        context_overlay_signal_backfill_days=15,
        context_overlay_signal_backfill_step_days=3,
        context_overlay_signal_backfill_limit=12,
        context_overlay_signal_backfill_maturity_buffer_days=-1,
        skip_signal_quality_promotion=True,
    )

    signal_cmd = model_training_runner._build_signal_quality_command(args)
