def test_research_evidence_runner_runs_evaluators_without_manual_promotion(monkeypatch):
    modules: list[str] = []

    def fake_run_json_command(cmd):
        module = cmd[cmd.index("-m") + 1]
        modules.append(module)
        if module == "advisory.signal_quality_evaluator":
            return {"status": "ok", "summary_rows": 2}
        if module == "advisory.signal_quality_family_report":
            return {"status": "ok", "candidate_helpful_count": 1}
        if module == "advisory.signal_quality_split_report":
            return {
                "status": "ok",
                "research_queue": {"candidate_build_count": 1, "negative_control_count": 0},
            }
        if module == "advisory.signal_quality_split_evaluator":
            return {"status": "ok", "meta": {"spec_count": 1, "summary_rows": 1}}
        if module == "advisory.adversarial_review_evaluator":
            return {"status": "ok", "evaluation_rows": 3, "summary_rows": 1}
        if module == "advisory.action_transition_evaluator":
            return {"status": "ok", "evaluation_rows": 4, "summary_rows": 1, "meta": {"signal_rows": 4}}
        raise AssertionError(f"unexpected command: {' '.join(cmd)}")

    monkeypatch.setattr(research_evidence_runner, "_run_json_command", fake_run_json_command)

    args = research_evidence_runner.parse_args(
        [
            "--include-signal-quality-split-reports",
            "--skip-context-overlay-signal-backfill",
            "--skip-event-evidence-store",
            "--skip-causal-event-memory",
            "--skip-negative-pressure-evaluator",
            "--skip-context-watch-evaluator",
            "--skip-action-evidence-provenance",
        ]
    )
    payload = research_evidence_runner.run_research_evidence(args)
    evidence = payload["research_evidence"]

    assert "advisory.signal_quality_evaluator" in modules
    assert "advisory.signal_quality_split_evaluator" in modules
    assert "advisory.adversarial_review_evaluator" in modules
    assert "advisory.action_transition_evaluator" in modules
    assert "advisory.signal_quality_promotion" not in modules
    assert evidence["runner"] == "advisory.research_evidence_runner"
    assert evidence["manual_review_rows_may_be_created"] is False
    assert evidence["manual_review_row_reason"] == "disabled_by_skip_signal_quality_promotion"
    assert evidence["authority"] == "research_only"
    assert evidence["broker_execution_allowed"] is False
    assert evidence["policy_auto_promotion_allowed"] is False
    readiness = evidence["readiness_summary"]
    assert readiness["status"] == "candidate_evidence_available"
    assert readiness["candidate_component_count"] >= 2
    assert readiness["broker_execution_allowed"] is False
    assert readiness["policy_auto_promotion_allowed"] is False
    assert readiness["authority_violation_count"] == 0
    assert readiness["authority_violation_components"] == []
    assert "signal_quality_family_report" in readiness["candidate_components"]
    assert "signal_quality_split_queue" in readiness["candidate_components"]
    component_status = {row["component"]: row for row in evidence["component_status"]}
    assert component_status["signal_quality_split_evaluator"]["status"] == "monitor"
    assert component_status["context_watch_evaluator"]["status"] == "skipped"
    assert all(int(row.get("authority_violation_count") or 0) == 0 for row in component_status.values())


def test_research_evidence_readiness_fails_closed_on_authority_violation():
    unsafe = model_training_runner._component_status(
        "unsafe_context_component",
        {
            "status": "ok",
            "evaluation_rows": 12,
            "ready_for_policy_review": True,
            "authority_contract": {
                "broker_execution_allowed": "true",
                "nested": {"portfolio_mutation_allowed": 1},
            },
        },
    )
    safe = model_training_runner._component_status(
        "safe_context_component",
        {
            "status": "ok",
            "evaluation_rows": 12,
            "ready_for_policy_review": True,
            "authority_contract": {
                "broker_execution_allowed": False,
                "policy_auto_promotion_allowed": False,
            },
        },
    )

    summary = model_training_runner._build_research_evidence_readiness_summary([unsafe, safe])

    assert unsafe["status"] == "authority_violation"
    assert unsafe["usable_for_review"] is False
    assert unsafe["authority_violation_count"] == 2
    assert summary["status"] == "error"
    assert summary["candidate_components"] == ["safe_context_component"]
    assert summary["authority_violation_count"] == 2
    assert summary["authority_violation_components"][0]["component"] == "unsafe_context_component"
    assert summary["broker_execution_allowed"] is False
    assert summary["policy_auto_promotion_allowed"] is False
    assert "authority-boundary" in summary["operator_action"]


def test_research_evidence_readiness_summary_marks_empty_beta_and_baseline_blockers():
    components = [
        model_training_runner._component_status("empty_context", {"status": "ok", "evaluation_rows": 0, "summary_rows": 0}),
        model_training_runner._component_status(
            "beta_context",
            {"status": "benchmark_beta_not_overlay_alpha", "family_count": 2, "benchmark_beta_not_overlay_alpha_count": 2},
        ),
        model_training_runner._component_status(
            "under_baselined_split",
            {"status": "ok", "meta": {"summary_rows": 1}, "readiness_contract": {"status": "technical_baseline_unavailable"}},
        ),
    ]
    summary = model_training_runner._build_research_evidence_readiness_summary(components)

    assert summary["status"] == "not_ready"
    assert summary["candidate_component_count"] == 0
    assert summary["blocker_count"] == 3
    assert summary["authority"] == "research_only_no_policy_or_broker_authority"
    assert summary["broker_execution_allowed"] is False
    assert {item["status"] for item in summary["blocker_components"]} == {"empty", "benchmark_beta_only", "under_baselined"}


def test_research_evidence_component_status_consumes_signal_quality_promotion_readiness():
    candidate = model_training_runner._component_status(
        "signal_quality_family_report",
        {
            "status": "ok",
            "family_count": 3,
            "promotion_readiness": {
                "status": "candidate_families_ready_for_review",
                "candidate_helpful_families": ["announcement_context"],
                "benchmark_or_attribution_blocked_families": [],
                "broker_execution_allowed": False,
                "policy_auto_promotion_allowed": False,
            },
        },
    )
    blocked = model_training_runner._component_status(
        "signal_quality_family_report",
        {
            "status": "ok",
            "family_count": 3,
            "promotion_readiness": {
                "status": "blocked_by_benchmark_or_attribution",
                "candidate_helpful_families": [],
                "benchmark_or_attribution_blocked_families": ["macro_context"],
                "broker_execution_allowed": False,
                "policy_auto_promotion_allowed": False,
            },
        },
    )

    assert candidate["status"] == "candidate_for_review"
    assert candidate["usable_for_review"] is True
    assert candidate["rows"]["candidate_count"] == 1
    assert candidate["reason"] == "candidate_families_ready_for_review"
    assert blocked["status"] == "benchmark_beta_only"
    assert blocked["usable_for_review"] is False
    assert blocked["rows"]["beta_only_count"] == 1
    assert blocked["reason"] == "blocked_by_benchmark_or_attribution"


def test_operator_health_research_evidence_run_summary_missing_log_surfaces_research_blocker(tmp_path):
    section = operator_health.check_research_evidence_run_summary(log_dir=tmp_path)
    hints = operator_health.build_fix_hints({"research_evidence_run_summary": section})
    trust = operator_health.build_trust_gate({"research_evidence_run_summary": section})
    blockers = operator_health.build_current_blockers({"research_evidence_run_summary": section}, hints, limit=10)

    assert section["status"] == "warn"
    assert section["usable"] is False
    assert section["ready_for_research_review"] is False
    assert section["reasons"] == ["missing_research_evidence_log"]
    assert section["broker_execution_allowed"] is False
    assert section["policy_auto_promotion_allowed"] is False
    hint = next(row for row in hints if row["details"].get("section") == "research_evidence_run_summary")
    assert "./all_research_evidence.sh" in hint["commands"]
    assert hint["details"]["broker_execution_allowed"] is False
    assert hint["details"]["policy_auto_promotion_allowed"] is False
    trust_check = next(row for row in trust["checks"] if row["key"] == "research_evidence_run_summary")
    assert trust_check["details"]["broker_execution_allowed"] is False
    assert trust_check["details"]["policy_auto_promotion_allowed"] is False
    blocker = next(row for row in blockers["rows"] if row["details"].get("section") == "research_evidence_run_summary")
    assert blocker["category"] == "research_evidence"


