    row = _rule_engine_strong_candidate_row()
    row["market_cap"] = 5_000.0
    row["avg_traded_value_20d"] = 250_000_000.0
    setup = {
        **_rule_engine_regime_block_setup(),
        "market_cap_max": 4_500.0,
        "min_avg_traded_value_20d": 300_000_000,
    }

    state, evaluation, rejections = rule_engine.evaluate_setup_row(
        row,
        regime_name="RISK_OFF",
        overlay_name="NONE",
        setup=setup,
    )

    assert state == "PASS_NOW"
    assert rule_engine.is_context_only_soft_failure("regime:risk_off_blocked_context_only") is True
