    assert set(evaluation["soft_failures"]) >= {
        "regime:risk_off_blocked_context_only",
        "market_cap:above_target",
        "liquidity:below_target",
    }
    assert any(item["reason_code"] == "regime_blocked_context_only" and item["severity"] == "soft" for item in rejections)


