def test_rule_engine_missing_regime_context_is_diagnostic_by_default(monkeypatch):
    events = []
    screener_date = pd.Timestamp("2026-04-01T00:00:00Z")
    row = _rule_engine_strong_candidate_row()
    row["symbol"] = "ABC"
    row["company_master_id"] = "nse:ABC"
    technical = pd.DataFrame([row.to_dict()])
    fundamentals = pd.DataFrame(
        [
            {
                "symbol": "ABC",
                "company_master_id": "nse:ABC",
                "fundamentals_snapshot_date": screener_date,
                "fundamentals_freshness_status": "fresh",
            }
        ]
    )
    universe = pd.DataFrame(
        [
            {
                "screener_date": screener_date,
                "screener_slug": "quality-breakout",
                "screener_name": "Quality Breakout",
                "symbol": "ABC",
                "exchange": "NSE",
                "company_master_id": "nse:ABC",
                "rank": 1,
            }
        ]
    )
    setup = {
        **_rule_engine_regime_block_setup(),
        "setup_id": "QUALITY_BREAKOUT_TEST",
        "setup_name": "Quality Breakout Test",
        "screeners": ["quality-breakout"],
        "blocked_regimes": [],
    }

    monkeypatch.delenv(rule_engine.RULE_ENGINE_REQUIRE_REGIME_CONTEXT_ENV, raising=False)
    monkeypatch.setattr(rule_engine, "record_local_fallback_event", lambda **kwargs: events.append(kwargs) or kwargs)
    monkeypatch.setattr(rule_engine, "get_effective_dates", lambda _asof=None: {"screener_date": screener_date})
    monkeypatch.setattr(rule_engine, "load_regime", lambda _asof: None)
    monkeypatch.setattr(rule_engine, "load_overlay", lambda asof_date, regime_name=None: {"asof_date": asof_date, "overlay_name": "NONE", "overlay_reason": "test", "overlay_intensity": 0.0})
    monkeypatch.setattr(rule_engine, "load_active_theme_screener_mapping", lambda **_kwargs: {"theme_ids": [], "screener_slugs": []})
    monkeypatch.setattr(rule_engine, "load_setup_registry", lambda _path=None: [setup])
    monkeypatch.setattr(rule_engine, "load_technical", lambda _date: technical)
    monkeypatch.setattr(rule_engine, "load_intraday", lambda _date: pd.DataFrame())
    monkeypatch.setattr(rule_engine, "load_fundamentals", lambda _date: fundamentals)
    monkeypatch.setattr(rule_engine, "load_screener_universe", lambda *_args, **_kwargs: universe)

    candidates, rejections, meta = rule_engine.run_rule_engine(asof_date=screener_date, skip_snapshot_refresh=True, skip_intraday_prefetch=True)

    assert not candidates.empty
    assert candidates.iloc[0]["regime_name"] == rule_engine.DIAGNOSTIC_REGIME_NAME
    assert meta["regime_context_status"] == "missing"
    assert "regime:unknown_not_preferred" in json.loads(candidates.iloc[0]["soft_failures_json"])
    assert any(event["fallback_type"] == "rule_engine_regime_context_missing" for event in events)
    assert all(item != "missing_regime_snapshot" for item in rejections.get("reason_code", pd.Series(dtype="string")).dropna().tolist())


