def test_technical_engine_emits_near_pivot_for_constructive_setup_without_trigger():
    row = _technical_engine_base_row()
    row["breakout_day_volume_vs_20d"] = 0.9
    row["pivot_distance_20d_pct"] = 1.8
    row["support_distance_20d_pct"] = 8.0
    out = technical_engine.evaluate_pre_entry_state(row)
    assert out["technical_state"] == "NEAR_PIVOT"
    assert out["technical_setup_archetype"] == "constructive_base_near_pivot"
    assert "volatility_compression" in out["technical_setup_quality"]["quality_flags"]
    trigger_contract = out["technical_setup_quality"]["entry_trigger_diagnostics"]
    assert trigger_contract["status"] == "blocked"
    assert trigger_contract["broker_execution_allowed"] is False
    assert out["technical_setup_quality"]["nearest_entry_trigger_type"] in {
        "breakout",
        "breakout_retest",
        "reclaim",
        "trend_pullback",
    }
    blocker_codes = {
        blocker["code"]
        for blockers in trigger_contract["all_trigger_blockers"].values()
        for blocker in blockers
    }
    assert "breakout_volume_below_min" in blocker_codes
    assert "pivot_not_cleared" in blocker_codes
    assert "too_far_from_support" in blocker_codes
    buy_readiness = out["technical_setup_quality"]["buy_readiness"]
    assert buy_readiness["status"] == "blocked"
    assert buy_readiness["broker_execution_allowed"] is False
    buy_blocker_codes = {item["code"] for item in buy_readiness["blockers"]}
    assert "entry_trigger_missing" in buy_blocker_codes


