def test_recommendation_diagnostics_summarizes_technical_trigger_blockers():
    quality = {
        "entry_trigger_status": "blocked",
        "nearest_entry_trigger_type": "breakout",
        "entry_trigger_blockers": [
            {
                "code": "breakout_volume_below_min",
                "archetype": "breakout",
                "metric": "breakout_day_volume_vs_20d",
                "current": 0.9,
                "operator": "gte",
                "threshold": 1.8,
            },
            {
                "code": "pivot_not_cleared",
                "archetype": "breakout",
                "metric": "pivot_distance_20d_pct",
                "current": 1.8,
                "operator": "lte",
                "threshold": 0.5,
            },
        ],
        "entry_trigger_diagnostics": {
            "nearest_trigger_type": "breakout",
            "nearest_trigger_blocker_count": 2,
        },
        "buy_readiness": {
            "status": "blocked",
            "blockers": [
                {
                    "code": "entry_trigger_missing",
                    "category": "trigger",
                },
                {
                    "code": "technical_total_below_buy_min",
                    "category": "total_score",
                    "metric": "technical_total_score",
                    "current": 72.0,
                    "operator": "gte",
                    "threshold": 78.0,
                    "gap_to_threshold": 6.0,
                },
            ],
            "broker_execution_allowed": False,
        },
    }
    candidates = pd.DataFrame(
        [
            {
                "symbol": "ABC",
                "setup_id": "TECH_TEST",
                "candidate_state": "WATCH_BREAKOUT",
                "technical_state": "NEAR_PIVOT",
                "technical_trigger_type": None,
                "technical_setup_archetype": "constructive_base_near_pivot",
                "technical_setup_quality_json": json.dumps(quality),
                "setup_score": 0.72,
                "technical_score": 0.81,
                "rule_pass": False,
                "watch_enabled": True,
            }
        ]
    )

    summary = recommendation_diagnostics.summarize_upstream_candidates(candidates)
    blockers = summary["technical_entry_readiness"]["technical_trigger_blockers"]

    assert blockers["status"] == "trigger_blocker_contract_available"
    assert blockers["nearest_trigger_counts"] == {"breakout": 1}
    assert blockers["blocker_counts"]["breakout_volume_below_min"] == 1
    assert blockers["blocker_counts"]["pivot_not_cleared"] == 1
    assert blockers["broker_execution_allowed"] is False
    assert blockers["samples"][0]["symbol"] == "ABC"
    readiness = summary["technical_entry_readiness"]["buy_readiness_blockers"]
    assert readiness["status"] == "buy_readiness_contract_available"
    assert readiness["blocker_counts"]["entry_trigger_missing"] == 1
    assert readiness["blocker_counts"]["technical_total_below_buy_min"] == 1
    assert readiness["broker_execution_allowed"] is False


