def test_technical_threshold_calibration_attaches_point_in_time_forward_returns():
    signals = pd.DataFrame(
        [
            {"asof_date": pd.Timestamp("2026-05-01T00:00:00Z"), "symbol": "ABC", "technical_total_score": 80.0},
            {"asof_date": pd.Timestamp("2026-05-02T00:00:00Z"), "symbol": "ABC", "technical_total_score": 80.0},
        ]
    )
    prices = pd.DataFrame(
        [
            {"symbol": "ABC", "date": pd.Timestamp("2026-05-01T00:00:00Z"), "close": 90.0},
            {"symbol": "ABC", "date": pd.Timestamp("2026-05-04T00:00:00Z"), "close": 100.0},
            {"symbol": "ABC", "date": pd.Timestamp("2026-05-05T00:00:00Z"), "close": 110.0},
            {"symbol": "ABC", "date": pd.Timestamp("2026-05-06T00:00:00Z"), "close": 121.0},
        ]
    )

    out = technical_threshold_calibration.attach_forward_returns(signals, prices, horizons=[2])

    contract = json.loads(out.iloc[0]["point_in_time_return_contract_json"])
    assert contract["same_day_price_allowed"] is False
    assert contract["forward_returns_are_labels_only"] is True
    assert contract["entry_rule"] == "Use first available close strictly after signal asof_date."
    assert out.iloc[0]["entry_date_h2"] == pd.Timestamp("2026-05-04T00:00:00Z")
    assert out.iloc[0]["exit_date_h2"] == pd.Timestamp("2026-05-05T00:00:00Z")
    assert round(float(out.iloc[0]["forward_return_h2"]), 4) == 0.1
    assert out.iloc[1]["entry_date_h2"] == pd.Timestamp("2026-05-04T00:00:00Z")
    assert out.iloc[0]["entry_close_h2"] == 100.0


def test_technical_threshold_calibration_ensure_tables_uses_schema_registry(monkeypatch):
    calls = []

    monkeypatch.setattr(technical_threshold_calibration, "apply_schema_migration", lambda **kwargs: calls.append(kwargs) or {"status": "applied"})

    technical_threshold_calibration.ensure_tables()

    assert len(calls) == 3
    assert calls[0]["migration_id"] == technical_threshold_calibration.TECHNICAL_THRESHOLD_SCHEMA_MIGRATION_ID
    assert calls[0]["metadata"]["tables"] == [
        technical_threshold_calibration.EVALUATIONS_TABLE,
        technical_threshold_calibration.SUMMARY_TABLE,
    ]
    assert any(technical_threshold_calibration.EVALUATIONS_TABLE in statement for statement in calls[0]["statements"])
    assert any(technical_threshold_calibration.SUMMARY_TABLE in statement for statement in calls[0]["statements"])
    assert any("UNIQUE (evaluated_at, config_id, horizon_days)" in statement for statement in calls[0]["statements"])
    assert any("DROP CONSTRAINT" in statement for statement in calls[0]["statements"])
    assert calls[1]["migration_id"] == technical_threshold_calibration.TECHNICAL_THRESHOLD_REPAIR_MIGRATION_ID
    assert calls[1]["metadata"]["partition_column"] == "evaluated_at"
    assert any("NOT ('evaluated_at' = ANY(rec.columns))" in statement for statement in calls[1]["statements"])
    assert calls[2]["migration_id"] == technical_threshold_calibration.TECHNICAL_ARCHETYPE_SUMMARY_MIGRATION_ID
    assert any("archetype_breakdown_json" in statement for statement in calls[2]["statements"])


def test_technical_threshold_calibration_persist_outputs_uses_timescale_safe_unique_keys(monkeypatch):
    writes: list[dict[str, object]] = []
    evaluated_at = pd.Timestamp("2026-06-05T12:00:00Z")
    evaluations = pd.DataFrame(
        [
            {
                "evaluated_at": evaluated_at,
                "config_id": "cfg",
                "horizon_days": 5,
                "threshold_config_json": "{}",
            }
        ]
    )
    summary = pd.DataFrame(
        [
            {
                "evaluated_at": evaluated_at,
                "horizon_days": 5,
                "best_config_id": "cfg",
            }
        ]
    )

    monkeypatch.setattr(technical_threshold_calibration, "ensure_tables", lambda: None)

    def fake_upsert(df, table, unique_keys, timescaledb_column=None):
        writes.append(
            {
                "table": table,
                "unique_keys": list(unique_keys),
                "timescaledb_column": timescaledb_column,
                "rows": len(df),
            }
        )

    monkeypatch.setattr(technical_threshold_calibration, "upsert_to_db", fake_upsert)

    technical_threshold_calibration.persist_outputs(evaluations, summary)

    assert writes == [
        {
            "table": technical_threshold_calibration.EVALUATIONS_TABLE,
            "unique_keys": ["evaluated_at", "config_id", "horizon_days"],
            "timescaledb_column": "evaluated_at",
            "rows": 1,
        },
        {
            "table": technical_threshold_calibration.SUMMARY_TABLE,
            "unique_keys": ["evaluated_at", "horizon_days"],
            "timescaledb_column": "evaluated_at",
            "rows": 1,
        },
    ]


