def test_technical_threshold_calibration_bounded_first_pass_reports_truncated_grid(monkeypatch):
    signals = pd.DataFrame(
        [
            {
                "asof_date": pd.Timestamp("2026-05-01T00:00:00Z"),
                "symbol": "WIN",
                "technical_state": "BUY_TRIGGERED",
                "technical_trigger_type": "breakout",
                "technical_trend_score": 18.0,
                "technical_structure_score": 22.0,
                "technical_participation_score": 13.0,
                "technical_relative_strength_score": 10.0,
                "technical_tradability_score": 7.0,
                "technical_total_score": 82.0,
            }
        ]
    )
    prices = pd.DataFrame(
        [
            {"symbol": "WIN", "date": pd.Timestamp("2026-05-04T00:00:00Z"), "close": 100.0},
            {"symbol": "WIN", "date": pd.Timestamp("2026-05-09T00:00:00Z"), "close": 108.0},
        ]
    )
    grid = [
        {
            "trend_min": 15.0 + idx,
            "structure_min": 18.0,
            "participation_min": 10.0,
            "relative_strength_min": 8.0,
            "tradability_min": 6.0,
            "ready_total_min": 70.0,
            "buy_total_min": 78.0,
        }
        for idx in range(4)
    ]

    monkeypatch.setattr(technical_threshold_calibration, "load_technical_signal_rows", lambda **_kwargs: signals.copy())
    monkeypatch.setattr(technical_threshold_calibration, "load_price_history_for_returns", lambda **_kwargs: prices.copy())
    monkeypatch.setattr(technical_threshold_calibration, "build_threshold_grid", lambda: list(grid))

    evaluations, summary, meta = technical_threshold_calibration.calibrate_thresholds(
        horizons=[5],
        return_threshold=0.02,
        cost_bps=0.0,
        min_signals=1,
        max_configs=2,
        progress_every=1,
    )

    assert len(evaluations) == 2
    assert len(summary) == 1
    assert meta["grid_count"] == 2
    assert meta["full_grid_count"] == 4
    assert meta["grid_truncated"] is True
    assert meta["max_configs"] == 2
    assert meta["promotion_eligible"] is False
    assert meta["policy_effect"] == "diagnostic_only_no_promotion"
    assert set(summary["recommendation"]) == {"bounded_first_pass_only"}


