    assert readiness["candidate_helpful_families"] == ["announcement_context", "trusted_context_rules"]
    assert readiness["suppressed_families"] == ["macro_context"]
    assert readiness["low_data_families"] == ["theme_context"]
    assert readiness["research_queue"][0]["task"] == "promotion_review"
    assert readiness["research_queue"][0]["authority_scope"] == "research_review_only"


