def test_signal_quality_split_report_latest_lookup_anchors_on_context_rows(monkeypatch):
    calls: list[tuple[str, Any]] = []

    def fake_sql_to_df(sql, params=None, **_kwargs):
        calls.append((sql, params))
        if "MAX(evaluated_at)" in sql:
            assert "context_variants" in params
            assert "technical_only" not in params["context_variants"]
            return pd.DataFrame([{"evaluated_at": pd.Timestamp("2026-06-01T00:00:00Z")}])
        assert "technical_only" in params["variants"]
        assert "technical_plus_announcement_context" in params["variants"]
        assert params["evaluated_at"] == pd.Timestamp("2026-06-01T00:00:00Z")
        return pd.DataFrame(
            [
                {
                    "evaluated_at": params["evaluated_at"],
                    "horizon_days": 5,
                    "variant": "technical_only",
                    "asof_date": pd.Timestamp("2026-05-20T00:00:00Z"),
                    "setup_id": "S1",
                    "symbol": "BASE",
                    "forward_return_after_cost": 0.01,
                    "hit_after_cost": True,
                    "context_sources_json": "[]",
                    "raw_context_json": "{}",
                },
                {
                    "evaluated_at": params["evaluated_at"],
                    "horizon_days": 5,
                    "variant": "technical_plus_announcement_context",
                    "asof_date": pd.Timestamp("2026-05-20T00:00:00Z"),
                    "setup_id": "S1",
                    "symbol": "AAA",
                    "forward_return_after_cost": 0.04,
                    "hit_after_cost": True,
                    "context_sources_json": json.dumps(
                        [{"source": "announcement_context", "class": "ORDER_WIN", "direction": "positive"}]
                    ),
                    "raw_context_json": "{}",
                },
            ]
        )

    monkeypatch.setattr(signal_quality_split_report, "sql_to_df", fake_sql_to_df)

    rows = signal_quality_split_report.load_split_evidence(source_family="announcement_context", horizons=[5])

    assert len(calls) == 2
    assert len(rows) == 2
    assert set(rows["variant"]) == {"technical_only", "technical_plus_announcement_context"}


