def test_signal_quality_window_runner_dry_run_is_research_only(monkeypatch):
    calls = {"persist": 0, "promotion": 0}

    def fake_evaluate_signal_quality(**_kwargs):
        summary = pd.DataFrame(
            [
                {
                    "evaluated_at": pd.Timestamp("2026-06-20T00:00:00Z"),
                    "horizon_days": 5,
                    "variant": "technical_plus_announcement_context",
                    "sample_count": 100,
                    "selected_count": 12,
                    "matured_count": 12,
                    "selection_rate": 0.12,
                    "avg_forward_return_after_cost": 0.03,
                    "hit_rate_after_cost": 0.58,
                    "positive_return_rate": 0.66,
                    "avg_benchmark_forward_return": 0.012,
                    "avg_excess_forward_return_after_cost": 0.023,
                    "excess_hit_rate_after_cost": 0.58,
                    "positive_excess_return_rate": 0.66,
                    "baseline_avg_forward_return_after_cost": 0.01,
                    "lift_vs_technical_only": 0.02,
                    "recommendation": "candidate_overlay_improves",
                    "sample_start": pd.Timestamp("2026-05-01T00:00:00Z"),
                    "sample_end": pd.Timestamp("2026-05-20T00:00:00Z"),
                }
            ]
        )
        return pd.DataFrame([{"symbol": "AAA"}]), summary, {"signal_rows": 1, "summary_rows": 1}

    monkeypatch.setattr(signal_quality_window_runner, "evaluate_signal_quality", fake_evaluate_signal_quality)
    monkeypatch.setattr(signal_quality_window_runner, "persist_outputs", lambda *_args, **_kwargs: calls.__setitem__("persist", calls["persist"] + 1))
    monkeypatch.setattr(
        signal_quality_window_runner,
        "generate_stable_family_promotion_reviews",
        lambda **_kwargs: calls.__setitem__("promotion", calls["promotion"] + 1) or {"status": "ok"},
    )

    result = signal_quality_window_runner.run_windows(
        [signal_quality_window_runner.EvaluationWindow("w1", pd.Timestamp("2026-05-01T00:00:00Z"), pd.Timestamp("2026-06-20T00:00:00Z"))],
        horizons=[5],
        dry_run=True,
        auto_promotion=True,
    )

    assert result["status"] == "ok"
    assert result["authority"] == "research_only"
    assert result["broker_execution_allowed"] is False
    assert result["policy_auto_promotion_allowed"] is False
    assert result["auto_promotion_executed"] is False
    assert result["candidate_window_count"] == 1
    assert result["stable_candidate_family_count"] == 0
    assert result["stability_report"]["families"][0]["classification"] == "one_window_candidate"
    assert result["promotion_gate"]["eligible_family_count"] == 0
    assert result["promotion_gate"]["families"][0]["decision"] == "hold_for_more_windows"
    assert result["promotion_gate"]["families"][0]["broker_execution_allowed"] is False
    assert result["windows"][0]["family_report"]["candidate_helpful_count"] == 1
    assert calls == {"persist": 0, "promotion": 0}


