    assert payload["announcements"]["context_overlay_rows"] == 1
    assert payload["announcements"]["storage_form_counts"] == {"structured_event_plus_summary": 1}
    assert payload["announcements"]["llm_evidence_mode_counts"] == {"event_tensor_plus_summary": 1}
    assert writes[0][0] == event_evidence_store.BHAVCOPY_EVIDENCE_TABLE
    assert writes[0][2] == ["asof_date", "symbol"]
    assert writes[1][0] == event_evidence_store.BHAVCOPY_CONTEXT_OVERLAYS_TABLE
    assert writes[1][2] == ["asof_date", "overlay_id"]
    assert writes[2][0] == event_evidence_store.ANNOUNCEMENT_EVIDENCE_TABLE
    assert writes[2][2] == ["published_on", "evidence_id"]
    assert writes[3][0] == event_evidence_store.ANNOUNCEMENT_CONTEXT_OVERLAYS_TABLE
    assert writes[3][2] == ["published_on", "overlay_id"]


