def test_event_evidence_store_classifies_announcement_storage_forms():
    structured = event_evidence_store.classify_announcement_storage_form(
        pd.Series(
            {
                "event_class": "ORDER_WIN",
                "direction": "positive",
                "what_happened": "The company won a large order with visible revenue impact.",
                "has_s3_evidence": True,
            }
        )
    )
    compact = event_evidence_store.classify_announcement_storage_form(
        pd.Series({"event_class": "REGULATORY_NOTICE", "direction": "negative", "attachment_url": "https://example.test/notice.pdf"})
    )
    summary_only = event_evidence_store.classify_announcement_storage_form(
        pd.Series({"subject": "Board approved capex plan with useful details for extraction."})
    )
    archive_only = event_evidence_store.classify_announcement_storage_form(pd.Series({"subject": ""}))

    assert structured["announcement_storage_form"] == "structured_event_plus_summary"
    assert structured["llm_evidence_mode"] == "event_tensor_plus_summary"
    assert structured["llm_review_ready"] is True
    assert compact["announcement_storage_form"] == "compact_structured_event"
