    assert summary_only["announcement_storage_form"] == "structured_event_plus_summary"
    assert summary_only["llm_evidence_mode"] == "summary_requires_event_extraction"
    assert archive_only["announcement_storage_form"] == "archived_raw_reference_only"
    assert archive_only["llm_review_ready"] is False


