def test_company_memory_summarizes_context_overlays_without_trade_authority():
    rows = [
        {
            "observed_at": pd.Timestamp("2026-06-01T09:00:00Z"),
            "context_source": "announcement_context",
            "direction": "positive",
            "context_class": "ORDER_WIN",
            "pressure_score": 0.8,
            "context_reason": "Order win creates watch pressure.",
            "authority_scope": "watchlist_pressure_only",
        },
        {
            "observed_at": pd.Timestamp("2026-06-01T08:00:00Z"),
            "context_source": "bhavcopy_context",
            "direction": "negative",
            "context_class": "distribution_or_pressure",
            "pressure_score": 0.6,
            "context_reason": "Distribution pressure.",
            "authority_scope": "watchlist_pressure_only",
        },
    ]

    summary = company_memory_review.summarize_company_context_overlays(rows)

    assert summary["row_count"] == 2
    assert summary["positive_count"] == 1
    assert summary["negative_count"] == 1
    assert summary["authority_scope"] == "watchlist_pressure_only"
    assert summary["action_policy_effect"] == "review_input_only_no_trade_authority"
    assert summary["broker_execution_allowed"] is False
    assert summary["source_family_counts"] == {"announcement_context": 1, "bhavcopy_context": 1}
    assert summary["top_overlays"][0]["source"] == "announcement_context"


