def test_company_memory_context_overlay_summary_respects_runtime_watch_contract():
    rows = [
        {
            "observed_at": pd.Timestamp("2026-06-01T09:00:00Z"),
            "context_source": "announcement_context",
            "direction": "positive",
            "context_class": "ORDER_WIN",
            "pressure_score": 0.8,
            "context_reason": "Order win has a helpful label but runtime contract blocks watch priority.",
            "authority_scope": "watchlist_pressure_only",
        }
    ]
    reliability = {
        "families": [
            {
                "source_family": "announcement_context",
                "classification": "candidate_helpful",
                "runtime_policy_contract": {
                    "runtime_policy": "suppressed_annotation_only",
                    "allowed_runtime_uses": {
                        "watch_priority": False,
                        "de_risk_review": False,
                        "broker_execution": False,
                    },
                },
                "context_class_diagnostics": [
                    {"context_class": "ORDER_WIN", "classification": "candidate_helpful"}
                ],
            }
        ]
    }

    summary = company_memory_review.summarize_company_context_overlays(rows, source_family_reliability=reliability)

    assert summary["positive_count"] == 1
    assert summary["effective_positive_count"] == 0
    assert summary["reliability_suppressed_count"] == 1
    suppressed = summary["top_suppressed_overlays"][0]
    assert suppressed["runtime_policy_contract_suppressed"] is True
    assert suppressed["runtime_policy_contract_suppression_reason"] == "watch_priority_not_allowed"
    assert suppressed["source_family_reliability"]["runtime_policy_contract"]["allowed_runtime_uses"]["watch_priority"] is False
    assert summary["broker_execution_allowed"] is False


