def test_company_memory_deterministic_review_uses_context_overlay_pressure():
    context = {
        "symbol": "ABC",
        "technical": [{"rs_vs_benchmark": 0.03}],
        "candidates": [{"technical_score": 81.0}],
        "announcement_evidence": [],
        "bhavcopy_evidence": [],
        "event_policy": [],
        "actions": [],
        "wait_signals": [],
        "context_overlays": [
            {
                "context_source": "announcement_context",
                "direction": "positive",
                "context_class": "ORDER_WIN",
                "pressure_score": 0.8,
                "authority_scope": "watchlist_pressure_only",
            }
        ],
    }
    context["context_overlay_summary"] = company_memory_review.summarize_company_context_overlays(context["context_overlays"])
    context["evidence_source_contract"] = company_memory_review.build_evidence_source_contract(context)

    review = company_memory_review.deterministic_review(context)

    assert review.recommended_signal == "BUY"
