def test_action_reason_contract_includes_causal_event_memory_alignment():
    raw_context = {
        "causal_event_memory_summary": {
            "schema_version": 1,
            "authority_scope": "explain_only",
            "action_policy_effect": "explain_only_no_ranking_change",
            "memory_policy_effect": "memory_context_only_no_trade_authority",
            "portfolio_authority": "none",
            "broker_execution_allowed": False,
            "memory_count": 1,
            "positive_count": 1,
            "negative_count": 0,
            "mixed_count": 0,
            "contradiction_count": 0,
            "source_family_counts": {"announcement_context": 1},
            "top_memories": [
                {
                    "memory_id": "mem-1",
                    "source": "announcement_context",
                    "event_type": "ORDER_WIN",
                    "context_class": "ORDER_WIN",
                    "direction": "positive",
                    "event_state": "positive_watch_pressure",
                    "decayed_pressure_score": 0.75,
                    "freshness_days": 0.0,
                    "contradiction_state": "none",
                    "policy_effect": "memory_only_no_trade_authority",
                }
            ],
        }
    }
    row = pd.Series(
        {
            "asof_date": pd.Timestamp("2026-06-18T00:00:00Z"),
            "symbol": "ABC",
            "setup_id": "SETUP",
            "action_code": "BUY",
            "action_source": "portfolio",
            "source_action": "BUY",
            "execution_mode": "broker_order",
            "transaction_type": "BUY",
            "stop_price": 90.0,
            "reference_price": 100.0,
            "published_on": pd.Timestamp("2026-06-18T09:00:00Z"),
            "reference_price_asof": pd.Timestamp("2026-06-18T10:00:00Z"),
            "raw_context_json": json.dumps(raw_context, default=str),
        }
    )

    contract = action_recommender.build_recommendation_reason_contract(row)
    section = contract["evidence"]["causal_event_memory"]

    assert section["causal_event_memory_summary"]["broker_execution_allowed"] is False
    alignment = section["causal_event_memory_action_alignment"]
    assert alignment["alignment"] == "memory_supports_selected_action"
    assert alignment["supportive_memory_count"] == 1
    assert alignment["action_policy_effect"] == "explain_only_no_ranking_change"
    assert alignment["memory_policy_effect"] == "memory_context_only_no_trade_authority"
    assert alignment["broker_execution_allowed"] is False
    assert alignment["top_supporting_memories"][0]["memory_id"] == "mem-1"


