def test_signal_quality_promotion_loads_context_variant_coverage(monkeypatch):
    calls = []

    def fake_sql_to_df(sql, params=None, **_kwargs):
        calls.append((sql, params))
        if "context_sources_json" in sql:
            return pd.DataFrame(
                [
                    {"symbol": "AAA", "matured": True, "context_sources_json": json.dumps([{"source": "theme_context"}, {"source": "macro_context"}])},
                    {"symbol": "BBB", "matured": False, "context_sources_json": json.dumps([{"source": "theme_context"}])},
                ]
            )
        return pd.DataFrame(
            [
                {
                    "selected_rows": 40,
                    "matured_selected_rows": 35,
                    "context_selected_rows": 18,
                    "context_matured_rows": 16,
                    "context_symbols": 7,
                    "avg_selected_context_overlay_count": 1.4,
                    "max_selected_context_overlay_count": 3,
                }
            ]
        )

    monkeypatch.setattr(signal_quality_promotion, "sql_to_df", fake_sql_to_df)

    coverage = signal_quality_promotion.load_context_variant_coverage(
        evaluated_at="2026-06-20T00:00:00Z",
        horizon_days=5,
        variant="technical_plus_all_context",
    )

    assert all(signal_quality_promotion.EVALUATIONS_TABLE in call[0] for call in calls)
    assert calls[0][1]["variant"] == "technical_plus_all_context"
    assert calls[1][1]["variant"] == "technical_plus_all_context"
    assert coverage["context_variant"] is True
    assert coverage["context_selected_rows"] == 18
    assert coverage["context_matured_rows"] == 16
    assert coverage["context_symbols"] == 7
    assert coverage["context_source_families"] == 2
    assert coverage["context_source_family_counts"] == {"theme_context": 2, "macro_context": 1}

    family_coverage = signal_quality_promotion.load_context_variant_coverage(
        evaluated_at="2026-06-20T00:00:00Z",
        horizon_days=5,
        variant="technical_plus_theme_context",
    )
    assert family_coverage["context_variant_source_family"] == "theme_context"
    assert family_coverage["context_family_selected_rows"] == 2
    assert family_coverage["context_family_matured_rows"] == 1
    assert family_coverage["context_family_symbols"] == 2


