def test_setup_registry_loads_signal_quality_overlay_rules_as_review_only(tmp_path):
    config_path = tmp_path / "advisory_setups.yaml"
    config_path.write_text(
        """signal_quality_overlay_rules:
  - authority: review_input_only
    broker_execution_allowed: false
    policy_auto_promotion_allowed: false
    context_source_family: announcement_context
    minimum_context_family_selected_rows: 10
    minimum_context_family_matured_rows: 10
    minimum_context_family_symbols: 5
    minimum_horizon_days: 5
    minimum_lift_vs_technical_only: 0.02
    minimum_matured_rows: 40
    overlay: technical_plus_announcement_context
    status: disabled_review_candidate
  - authority: live_policy
    broker_execution_allowed: true
    minimum_horizon_days: 10
    overlay: unsafe_overlay
""",
        encoding="utf-8",
    )

    payload = setup_registry.load_signal_quality_overlay_rules(str(config_path))

    assert payload["status"] == "issues_found"
    assert payload["summary"]["row_count"] == 2
    assert payload["summary"]["valid_count"] == 1
    assert payload["operator_boundary"]["broker_execution_enabled"] is False
    valid = payload["rules"][0]
    assert valid["overlay"] == "technical_plus_announcement_context"
    assert valid["context_source_family"] == "announcement_context"
    assert valid["usable_for_live_policy"] is False
    invalid = payload["rules"][1]
    assert invalid["valid"] is False
    assert {issue["code"] for issue in invalid["issues"]} >= {"unsafe_authority", "unsafe_broker_execution"}


