    assert missing_reason["identity_validation_status"] == "unresolved_company_master"
    assert missing_reason["policy_effect"] == "suppress_context_identity_unresolved_no_trade_authority"
    assert "identity/source blocker" in rows["MISSING"]["watch_reason_detail"]


