def test_watchlist_builder_hard_ohlcv_blockers_include_durable_history_issues(monkeypatch):
    asof_date = pd.Timestamp("2026-06-20T00:00:00Z")
    monkeypatch.setattr(watchlist_builder, "WATCHLIST_CONTEXT_OVERLAY_OHLCV_ISSUE_EXCLUSION_ATTEMPTS", 2)
    monkeypatch.setattr(
        watchlist_builder,
        "table_exists",
        lambda table_name: table_name == watchlist_builder.IDENTITY_ISSUES_TABLE,
    )

    def fake_sql_to_df(sql, params=None, **kwargs):
        assert params[1] == 2
        return pd.DataFrame(
            [
                {
                    "symbol": "BLOCKED",
                    "issue_key": "dhan_ohlcv_history_unavailable:stock:NSE:BLOCKED",
                    "issue_type": "dhan_ohlcv_history_unavailable",
                    "status": "open",
                    "source": "advisory.data_sync.ensure_symbol_ohlcv",
                    "error_text": "Dhan API request failed with status 400",
                    "suggested_action": "Repair or explicitly exclude.",
                    "attempt_count": 3,
                    "last_seen_at": pd.Timestamp("2026-06-19T00:00:00Z"),
                    "context_json": "{}",
                }
            ]
        )

    monkeypatch.setattr(watchlist_builder, "sql_to_df", fake_sql_to_df)

    blockers = watchlist_builder._load_context_hard_ohlcv_blockers(
        symbols=["BLOCKED", "GOOD"],
        asof_date=asof_date,
    )

    assert sorted(blockers) == ["BLOCKED"]
