def test_watchlist_builder_context_overlay_exact_cutoff_stays_point_in_time(monkeypatch):
    direct: dict[str, object] = {}
    sector: dict[str, object] = {}
    monkeypatch.setattr(watchlist_builder, "table_exists", lambda table_name: True)

    def fake_columns(table_name):
        if table_name == watchlist_builder.ANNOUNCEMENT_CONTEXT_OVERLAYS_TABLE:
            return {"symbol", "published_on", "direction", "production_status", "authority_scope", "pressure_score", "overlay_id", "event_class"}
        return {"asof_date", "symbol", "direction", "sector_name", "sector_code", "production_status", "authority_scope", "pressure_score", "overlay_id", "theme_id", "theme_reason"}

    def fake_sql_to_df(sql, params=None, **kwargs):
        target = direct if "published_on" in sql else sector
        target["sql"] = sql
        target["params"] = params
        return pd.DataFrame()

    monkeypatch.setattr(watchlist_builder, "table_columns", fake_columns)
