    assert by_source["theme_context_negative"]["classification"] == "harmful_false_positive_pressure"
    assert by_source["theme_context_negative"]["recommendation"] == "suppress_or_rework_negative_pressure_source_before_policy_influence"
    assert by_source["theme_context_negative"]["false_positive_rate_after_cost"] == pytest.approx(1.0)
    assert by_source["theme_context_negative"]["broker_execution_allowed"] is False


