def test_context_overlay_reliability_report_maps_fast_watch_outcomes_to_family_classes():
    watch_summary = pd.DataFrame(
        [
            {
                "evaluated_at": pd.Timestamp("2026-06-20T00:00:00Z"),
                "horizon_days": 5,
                "signal_source": "context_overlay_watch",
                "effect_type": "context_overlay_watch_pressure",
                "source_context": "announcement_context",
                "matured_count": 12,
                "symbol_count": 10,
                "avg_forward_return": 0.05,
                "avg_benchmark_forward_return": 0.01,
                "avg_watch_return_after_cost": 0.0475,
                "avg_excess_watch_return_after_cost": 0.0375,
                "opportunity_hit_rate_after_cost": 0.6,
                "excess_opportunity_hit_rate_after_cost": 0.6,
                "negative_after_cost_rate": 0.2,
                "negative_excess_after_cost_rate": 0.2,
                "classification": "opportunity_candidate",
            },
            {
                "evaluated_at": pd.Timestamp("2026-06-20T00:00:00Z"),
                "horizon_days": 5,
                "signal_source": "context_overlay_watch",
                "effect_type": "context_overlay_watch_pressure",
                "source_context": "macro_context",
                "matured_count": 12,
                "symbol_count": 10,
                "avg_forward_return": -0.04,
                "avg_benchmark_forward_return": 0.01,
                "avg_watch_return_after_cost": -0.0425,
                "avg_excess_watch_return_after_cost": -0.0525,
                "opportunity_hit_rate_after_cost": 0.2,
                "excess_opportunity_hit_rate_after_cost": 0.2,
                "negative_after_cost_rate": 0.8,
                "negative_excess_after_cost_rate": 0.8,
                "classification": "harmful_watch_noise",
            },
        ]
    )
    negative_summary = pd.DataFrame(
        [
            {
                "evaluated_at": pd.Timestamp("2026-06-20T00:00:00Z"),
                "horizon_days": 5,
                "signal_source": "announcement_context_negative",
                "effect_type": "direct_context_derisk_pressure",
                "source_context": "exchange_context",
                "matured_count": 12,
                "symbol_count": 10,
                "avg_forward_return": -0.05,
                "avg_benchmark_forward_return": -0.01,
                "avg_avoided_return_after_cost": 0.0475,
                "avg_excess_avoided_return_after_cost": 0.0375,
                "protective_hit_rate_after_cost": 0.6,
                "excess_protective_hit_rate_after_cost": 0.6,
                "false_positive_rate_after_cost": 0.2,
                "false_positive_excess_rate_after_cost": 0.2,
                "classification": "protective_candidate",
            }
        ]
    )

    report = context_overlay_reliability_report.build_reliability_report(
        watch_summary=watch_summary,
        negative_summary=negative_summary,
        min_matured_rows=10,
    )
    by_family = {row["source_family"]: row for row in report["families"]}

    assert report["authority"] == "research_only"
    assert report["broker_execution_allowed"] is False
    assert report["empty_reason"] is None
    assert report["input_coverage"]["context_watch"]["row_count"] == 2
    assert report["input_coverage"]["negative_pressure"]["row_count"] == 1
    assert report["input_coverage"]["context_watch"]["benchmark_attribution_status"] == "available"
    assert report["input_coverage"]["negative_pressure"]["benchmark_attribution_status"] == "available"
    assert report["recommended_commands"] == []
    assert by_family["announcement_context"]["classification"] == "candidate_helpful"
    assert by_family["macro_context"]["classification"] == "hurts_or_no_lift"
    assert by_family["exchange_context"]["classification"] == "protective_candidate"
    assert by_family["announcement_context"]["runtime_policy_contract"]["runtime_policy_effect"] == "watch_priority_allowed_no_buy_authority"
    assert by_family["announcement_context"]["runtime_policy_contract"]["allowed_runtime_uses"]["watch_priority"] is True
    assert by_family["announcement_context"]["runtime_policy_contract"]["broker_execution_allowed"] is False
    assert by_family["exchange_context"]["runtime_policy_contract"]["runtime_policy_effect"] == "de_risk_review_allowed_no_sell_authority"
    assert by_family["exchange_context"]["runtime_policy_contract"]["allowed_runtime_uses"]["de_risk_review"] is True
    assert by_family["macro_context"]["runtime_policy_contract"]["runtime_policy_effect"] == "suppressed_annotation_only"


def test_context_evaluators_report_benchmark_attribution_coverage():
    evaluations = pd.DataFrame(
        [
            {"matured": True, "benchmark_forward_return": 0.01},
            {"matured": True, "benchmark_forward_return": None},
            {"matured": False, "benchmark_forward_return": None},
        ]
    )

    watch = context_watch_evaluator._benchmark_attribution_coverage(evaluations)
    negative = negative_pressure_evaluator._benchmark_attribution_coverage(evaluations)

    assert watch == {
        "matured_rows": 2,
        "benchmark_attributed_matured_rows": 1,
        "benchmark_missing_matured_rows": 1,
        "benchmark_attribution_status": "partial",
    }
    assert negative == watch
    assert context_watch_evaluator._benchmark_attribution_coverage(pd.DataFrame())["benchmark_attribution_status"] == "no_matured_labels"
    assert negative_pressure_evaluator._benchmark_attribution_coverage(pd.DataFrame())["benchmark_attribution_status"] == "no_matured_labels"


def test_context_overlay_reliability_report_no_data_explains_missing_inputs():
    report = context_overlay_reliability_report.build_reliability_report(
        watch_summary=pd.DataFrame(),
        negative_summary=pd.DataFrame(),
        min_matured_rows=10,
    )
    text = context_overlay_reliability_report.format_text_report(report)

    assert report["status"] == "no_data"
    assert report["empty_reason"] == "no_context_watch_or_negative_pressure_summary_rows"
    assert report["input_coverage"]["context_watch"]["row_count"] == 0
    assert report["input_coverage"]["negative_pressure"]["row_count"] == 0
    assert report["input_coverage"]["context_watch"]["benchmark_attribution_status"] == "no_matured_labels"
    assert [item["command"] for item in report["recommended_commands"]] == [
        "python -m advisory.context_watch_evaluator --horizons 5 10 20",
        "python -m advisory.negative_pressure_evaluator --horizons 5 10 20",
        "python -m advisory.context_overlay_reliability_report --horizons 5 10 20 --format text",
    ]
    assert "empty_reason: no_context_watch_or_negative_pressure_summary_rows" in text
    assert "recommended_commands:" in text


