def test_context_overlay_reliability_report_converts_and_persists_rows(monkeypatch):
    persisted: list[tuple[str, pd.DataFrame, list[str]]] = []
    schema_calls: list[str] = []
    report = {
        "evaluated_at": pd.Timestamp("2026-06-20T00:00:00Z"),
        "families": [
            {
                "source_family": "announcement_context",
                "classification": "candidate_helpful",
                "total_selected_count": 12,
                "total_matured_count": 12,
                "watch_matured_count": 12,
                "negative_pressure_matured_count": 0,
                "avg_forward_return_after_cost": 0.04,
                "avg_hit_rate_after_cost": 0.6,
                "watch_horizons": [{"horizon_days": 5}],
                "negative_pressure_horizons": [],
                "authority": "research_only",
                "broker_execution_allowed": False,
                "policy_auto_promotion_allowed": False,
            }
        ],
    }

    monkeypatch.setattr(context_overlay_reliability_report, "ensure_tables", lambda: schema_calls.append("ensure"))
    monkeypatch.setattr(
        context_overlay_reliability_report,
        "upsert_to_db",
        lambda df, table, unique_keys: persisted.append((table, df.copy(), list(unique_keys))),
    )

    rows = context_overlay_reliability_report.report_to_rows(report)
    count = context_overlay_reliability_report.persist_reliability_report(report)

    assert rows.iloc[0]["source_family"] == "announcement_context"
    assert bool(rows.iloc[0]["broker_execution_allowed"]) is False
    assert json.loads(rows.iloc[0]["report_json"])["runtime_policy_contract"]["runtime_policy_effect"] == "watch_priority_allowed_no_buy_authority"
    assert json.loads(rows.iloc[0]["watch_horizons_json"])[0]["horizon_days"] == 5
    assert count == 1
    assert schema_calls == ["ensure"]
    assert persisted[0][0] == context_overlay_reliability_report.RELIABILITY_SUMMARY_TABLE
    assert persisted[0][2] == ["evaluated_at", "source_family"]


