def test_signal_refresh_context_overlay_diagnostics_explain_missing_sources(monkeypatch):
    available_tables = {
        signal_refresh.ANNOUNCEMENT_CONTEXT_OVERLAYS_TABLE,
        signal_refresh.WATCHLIST_TABLE,
        signal_refresh.PORTFOLIO_TABLE,
    }
    monkeypatch.setattr(signal_refresh, "table_exists", lambda table_name: table_name in available_tables)

    def fake_columns(table_name):
        if table_name == signal_refresh.ANNOUNCEMENT_CONTEXT_OVERLAYS_TABLE:
            return {"symbol", "published_on", "direction", "production_status", "authority_scope"}
        if table_name in {signal_refresh.WATCHLIST_TABLE, signal_refresh.PORTFOLIO_TABLE}:
            return {"asof_date"}
        return set()

    queries = []

    def fake_sql_to_df(sql, params=None, **kwargs):
        queries.append((sql, params, kwargs))
        if "positive_watch_rows" in sql:
            return pd.DataFrame([{"positive_watch_rows": 1, "negative_rows": 1, "active_authorized_rows": 2}])
        return pd.DataFrame([{"row_count": 2, "latest_date": pd.Timestamp("2026-06-20T00:00:00Z")}])

    monkeypatch.setattr(signal_refresh, "table_columns", fake_columns)
    monkeypatch.setattr(signal_refresh, "sql_to_df", fake_sql_to_df)

    diagnostics = signal_refresh.inspect_context_overlay_signal_inputs(asof_date=pd.Timestamp("2026-06-20T00:00:00Z"))

    assert diagnostics["asof_cutoff"] == pd.Timestamp("2026-06-21T00:00:00Z")
    assert diagnostics["asof_operator"] == "<"
    assert diagnostics["source_count"] == 5
    assert diagnostics["available_source_count"] == 1
    assert diagnostics["source_rows_total"] == 2
    assert diagnostics["active_authorized_rows_total"] == 2
    assert diagnostics["source_status"] == "context_overlay_rows_available"
    assert diagnostics["empty_reason"] is None
    announcement = [row for row in diagnostics["sources"] if row["source"] == "announcement_context"][0]
    assert announcement["positive_watch_rows"] == 1
    assert announcement["negative_rows"] == 1
    missing = [row for row in diagnostics["sources"] if row["source"] == "exchange_context"][0]
    assert missing["status"] == "missing_table"
    assert diagnostics["watchlist"]["status"] == "ok"
    assert diagnostics["portfolio"]["status"] == "ok"
    assert any("published_on < %(asof_date)s" in query[0] for query in queries)
    assert all(query[1]["asof_date"] == pd.Timestamp("2026-06-21T00:00:00Z") for query in queries if query[1])


