def test_signal_refresh_context_overlay_conversion_counts_policy_suppressed_positive_watch_rows(monkeypatch):
    raw = pd.DataFrame(
        [
            {
                "asof_date": pd.Timestamp("2026-06-20T00:00:00Z"),
                "symbol": "MISSING",
                "setup_score": 0.0,
                "watch_enabled": False,
                "candidate_state": "REJECT",
                "context_source": "announcement_context",
                "context_policy_effect": "suppress_context_identity_unresolved_no_trade_authority",
                "context_overlay_id": "missing-1",
                "watch_reason_detail": "identity/source blocker",
            }
        ]
    )
    raw_out, kept, suppressed = signal_refresh._split_positive_context_overlay_watch_targets(raw, limit=10)

    assert raw_out["symbol"].tolist() == ["MISSING"]
    assert kept.empty
    assert len(suppressed) == 1
    assert suppressed[0]["context_policy_effect"] == "suppress_context_identity_unresolved_no_trade_authority"
    assert "suppress_context_identity_unresolved_no_trade_authority" in suppressed[0]["suppression_reasons"]

    diagnostics = {
        "sources": [
            {
                "source": "announcement_context",
                "row_count": 1,
                "positive_watch_rows": 1,
                "negative_rows": 0,
                "active_authorized_rows": 1,
                "required_columns_present": True,
            }
        ]
    }
    summary = signal_refresh.summarize_context_overlay_conversion(
        diagnostics=diagnostics,
        raw_theme_targets=pd.DataFrame(),
        raw_direct_targets=pd.DataFrame(),
        raw_positive_watch_targets=raw_out,
        kept_theme_targets=pd.DataFrame(),
        kept_direct_targets=pd.DataFrame(),
        kept_positive_watch_targets=kept,
        reliability_suppressed=[],
        policy_suppressed=suppressed,
    )

    assert summary["raw_target_rows"] == 1
    assert summary["kept_target_rows"] == 0
    assert summary["policy_suppressed_target_rows"] == 1
    assert summary["identity_policy_suppressed_target_rows"] == 1
    row = summary["sources"][0]
    assert row["policy_suppressed_target_rows"] == 1
    assert row["identity_policy_suppressed_target_rows"] == 1
    assert row["policy_suppression_reason_counts"]["suppress_context_identity_unresolved_no_trade_authority"] == 1
    assert "positive_watch_targets_suppressed_by_watchlist_policy" in row["conversion_reasons"]
    assert "positive_watch_targets_suppressed_by_identity_source_policy" in row["conversion_reasons"]
    assert summary["policy_suppressed_samples"][0]["symbol"] == "MISSING"


def test_signal_refresh_causal_memory_targets_require_candidate_helpful_summary(monkeypatch):
    captured: dict[str, object] = {}
    monkeypatch.setattr(signal_refresh, "table_exists", lambda table_name: True)

    def fake_sql_to_df(query, params=None, **kwargs):
        calls = captured.setdefault("queries", [])
        calls.append(query)
        captured["params"] = params
        captured["kwargs"] = kwargs
        if "GROUP BY LOWER(TRIM(COALESCE(s.classification, 'unknown')))" in query:
            return pd.DataFrame(
                [
                    {
                        "classification": "candidate_helpful",
                        "memory_row_count": 1,
                        "symbol_count": 1,
                        "latest_evaluated_at": pd.Timestamp("2026-06-19T00:00:00Z"),
                    },
                    {
                        "classification": "hurts_or_no_lift",
                        "memory_row_count": 3,
                        "symbol_count": 2,
                        "latest_evaluated_at": pd.Timestamp("2026-06-19T00:00:00Z"),
                    },
                    {
                        "classification": "benchmark_beta_not_memory_alpha",
                        "memory_row_count": 4,
                        "symbol_count": 3,
                        "latest_evaluated_at": pd.Timestamp("2026-06-19T00:00:00Z"),
                    },
                    {
                        "classification": "needs_benchmark_attribution",
                        "memory_row_count": 2,
                        "symbol_count": 2,
                        "latest_evaluated_at": pd.Timestamp("2026-06-19T00:00:00Z"),
                    },
                ]
            )
        captured["target_params"] = params
        return pd.DataFrame(
            [
                {
                    "memory_asof_date": pd.Timestamp("2026-06-20T00:00:00Z"),
                    "memory_id": "cem-1",
                    "symbol": "ABC",
                    "context_source": "announcement_context",
                    "event_group": "announcement",
                    "event_type": "ORDER_WIN",
                    "context_class": "ORDER_WIN",
                    "direction": "positive",
                    "event_state": "positive_watch_pressure",
                    "pressure_score": 0.8,
                    "decayed_pressure_score": 0.7,
                    "event_count": 2,
                    "contradiction_state": "none",
                    "memory_reliability_classification": "candidate_helpful",
                    "memory_reliability_matured_count": 20,
                }
            ]
        )

    monkeypatch.setattr(signal_refresh, "sql_to_df", fake_sql_to_df)

    targets, diagnostics = signal_refresh.load_causal_memory_signal_targets(
        asof_date=pd.Timestamp("2026-06-20T00:00:00Z"),
        limit=10,
    )

    query = str((captured["queries"])[0])
    assert signal_refresh.CAUSAL_EVENT_MEMORY_TABLE in query
    assert signal_refresh.CAUSAL_EVENT_MEMORY_SUMMARY_TABLE in query
    assert "candidate_helpful" in query
    assert "decayed_pressure_score" in query
    assert diagnostics["status"] == "ok"
    assert diagnostics["target_rows"] == 1
    assert diagnostics["broker_execution_allowed"] is False
    assert diagnostics["classification_memory_row_counts"]["candidate_helpful"] == 1
    assert diagnostics["classification_memory_row_counts"]["hurts_or_no_lift"] == 3
    assert diagnostics["classification_memory_row_counts"]["benchmark_beta_not_memory_alpha"] == 4
    assert diagnostics["classification_memory_row_counts"]["needs_benchmark_attribution"] == 2
    assert diagnostics["harmful_or_no_lift_suppressed_memory_rows"] == 3
    assert diagnostics["benchmark_beta_not_memory_alpha_suppressed_memory_rows"] == 4
    assert diagnostics["needs_benchmark_attribution_suppressed_memory_rows"] == 2
    assert diagnostics["non_candidate_suppressed_memory_rows"] == 9
    assert diagnostics["min_excess_directional_helpfulness_score"] == signal_refresh.CAUSAL_MEMORY_MIN_EXCESS_DIRECTIONAL_HELPFULNESS_SCORE
    assert diagnostics["min_excess_direction_hit_rate"] == signal_refresh.CAUSAL_MEMORY_MIN_EXCESS_DIRECTION_HIT_RATE
    assert "avg_excess_directional_helpfulness_score" in query
    assert "excess_direction_hit_rate_after_cost" in query
    assert captured["target_params"]["min_excess_directional_helpfulness_score"] == signal_refresh.CAUSAL_MEMORY_MIN_EXCESS_DIRECTIONAL_HELPFULNESS_SCORE
    assert captured["target_params"]["min_excess_direction_hit_rate"] == signal_refresh.CAUSAL_MEMORY_MIN_EXCESS_DIRECTION_HIT_RATE
    assert diagnostics["suppression_policy"] == "only exact candidate_helpful causal-memory evaluator groups with positive benchmark-excess evidence can create review-only signals"
    assert targets.iloc[0]["symbol"] == "ABC"


