def test_signal_refresh_context_overlay_conversion_diagnostics_explain_macro_gap():
    diagnostics = {
        "sources": [
            {
                "source": "macro_context",
                "row_count": 5,
                "positive_watch_rows": 1,
                "negative_rows": 4,
                "active_authorized_rows": 5,
                "required_columns_present": True,
            }
        ]
    }

    summary = signal_refresh.summarize_context_overlay_conversion(
        diagnostics=diagnostics,
        raw_theme_targets=pd.DataFrame(),
        raw_direct_targets=pd.DataFrame(),
        raw_positive_watch_targets=pd.DataFrame(),
        kept_theme_targets=pd.DataFrame(),
        kept_direct_targets=pd.DataFrame(),
        kept_positive_watch_targets=pd.DataFrame(),
        reliability_suppressed=[],
    )

    assert summary["status"] == "source_rows_available_but_no_signal_targets_matched"
    assert summary["sources_with_conversion_gaps"] == 1
    row = summary["sources"][0]
    assert row["source"] == "macro_context"
    assert row["source_rows"] == 5
    assert row["positive_watch_source_rows"] == 1
    assert row["negative_source_rows"] == 4
    assert row["conversion_status"] == "not_converted"
    assert "sector_overlay_rows_did_not_match_market_context_universe_or_watch_candidate_filters" in row["conversion_reasons"]
    assert "negative_macro_context_rows_did_not_match_reviewable_watchlist_or_portfolio_exposure" in row["conversion_reasons"]
    assert row["broker_execution_allowed"] is False


