    assert len(events) == 1
    event = events[0]
    assert event["module"] == "data.dhanlive.ohlcv"
    assert event["fallback_type"] == "dhan_ohlcv_daily_symbol_sync_failed"
    assert event["source"] == dhan_ohlcv.DAILY_TABLE
