    assert "python -m advisory.signal_refresh --from-context-overlays --limit 50 --format text" in hint["commands"]
    assert "python -m advisory.signal_refresh --from-causal-memory --limit 25 --format text" in hint["commands"]
    assert "python -m advisory.recommendation_diagnostics --format text" in hint["commands"]
    assert "./all_watchers.sh" in hint["commands"]
    assert hint["details"]["missing_sources"] == ["advisory:signal_refresh:causal_memory"]
    assert hint["details"]["stale_sources"] == ["advisory:signal_refresh:context_overlays"]
    assert hint["details"]["error_sources"] == ["continuous_watch:action_refresh"]
    assert hint["details"]["unsafe_authority_sources"] == ["advisory:signal_refresh:context_overlays"]
    assert hint["details"]["source_contract_issue_sources"] == ["advisory:signal_refresh:context_overlays"]
    assert hint["details"]["algorithm_version_mismatch_sources"] == ["advisory:signal_refresh:context_overlays"]
    assert hint["details"]["unsafe_authority_count"] == 1
    assert hint["details"]["algorithm_version_mismatch_count"] == 1
    assert hint["details"]["malformed_source_contract_count"] == 2
    assert hint["details"]["signal_row_total"] == 4
    assert hint["details"]["identity_policy_suppressed_target_rows"] == 7
    assert hint["details"]["identity_policy_suppressed_sources"] == {"bhavcopy_context": 5, "exchange_context": 2}
    assert hint["details"]["broker_execution_allowed"] is False
    assert hint["details"]["portfolio_authority"] == "none"

    identity_hint = next(item for item in hints if item["title"] == "Context-overlay identity/source mapping is suppressing targets")
    assert "python -m advisory.operator_health --check identity_issues --skip-dhan" in identity_hint["commands"]
    assert "python -m advisory.identity_issues --format text" in identity_hint["commands"]
    assert identity_hint["details"]["identity_policy_suppressed_target_rows"] == 7
    assert identity_hint["details"]["identity_policy_suppressed_sources"] == {"bhavcopy_context": 5, "exchange_context": 2}


