def test_regime_overlay_json_helpers_record_fallback_telemetry(monkeypatch):
    from advisory import regime_overlay

    class AmbiguousMissing:
        def __str__(self):
            return "ambiguous-text"

    events: list[dict[str, Any]] = []
    monkeypatch.setattr(regime_overlay.pd, "isna", lambda _value: (_ for _ in ()).throw(TypeError("ambiguous missing")))
    monkeypatch.setattr(regime_overlay, "record_local_fallback_event", lambda **kwargs: events.append(kwargs) or kwargs)

    sentinel = AmbiguousMissing()
    assert regime_overlay._json_ready(sentinel) is sentinel
    assert regime_overlay._text(sentinel) == "ambiguous-text"
    assert regime_overlay._json_loads("{bad json", {"fallback": True}) == {"fallback": True}

    fallback_types = {event["fallback_type"] for event in events}
    assert "regime_overlay_json_ready_missing_check_failed" in fallback_types
