def test_signal_quality_split_evaluator_uses_schema_registry(monkeypatch):
    calls = []

    monkeypatch.setattr(signal_quality_split_evaluator, "apply_schema_migration", lambda **kwargs: calls.append(kwargs))

    signal_quality_split_evaluator.ensure_tables()

    assert len(calls) == 2
    call = calls[0]
    review_call = calls[1]
    assert call["migration_id"] == signal_quality_split_evaluator.SPLIT_EVALUATOR_SCHEMA_MIGRATION_ID
    assert review_call["migration_id"] == signal_quality_split_evaluator.SPLIT_REVIEW_SCHEMA_MIGRATION_ID
    assert call["metadata"]["authority"] == "research_only"
    assert review_call["metadata"]["authority"] == "manual_config_review_only"
    ddl = "\n".join(call["statements"] + review_call["statements"])
    assert signal_quality_split_evaluator.SPLIT_EVALUATIONS_TABLE in ddl
    assert signal_quality_split_evaluator.SPLIT_SUMMARY_TABLE in ddl
    assert signal_quality_split_evaluator.SPLIT_REVIEWS_TABLE in ddl
    assert signal_quality_split_evaluator.SPLIT_DECISIONS_TABLE in ddl
    assert "broker_execution_allowed BOOLEAN" in ddl


def test_signal_quality_split_evaluator_schema_only_cli_does_not_evaluate_or_persist(monkeypatch, capsys):
    calls = []

    monkeypatch.setattr(signal_quality_split_evaluator, "ensure_tables", lambda: calls.append("ensure_tables"))
    monkeypatch.setattr(
        signal_quality_split_evaluator,
        "evaluate_split_quality",
        lambda **_kwargs: (_ for _ in ()).throw(AssertionError("schema-only mode should not evaluate")),
    )
    monkeypatch.setattr(
        signal_quality_split_evaluator,
        "persist_outputs",
        lambda *_args, **_kwargs: (_ for _ in ()).throw(AssertionError("schema-only mode should not persist")),
    )
    monkeypatch.setattr(
        signal_quality_split_evaluator,
        "generate_stability_promotion_reviews",
        lambda **_kwargs: (_ for _ in ()).throw(AssertionError("schema-only mode should not generate reviews")),
    )

    assert signal_quality_split_evaluator.main(["--ensure-schema-only"]) == 0
    output = json.loads(capsys.readouterr().out)

    assert calls == ["ensure_tables"]
    assert output["status"] == "ok"
    assert output["mode"] == "ensure_schema_only"
    assert output["evaluations_table"] == signal_quality_split_evaluator.SPLIT_EVALUATIONS_TABLE
    assert output["summary_table"] == signal_quality_split_evaluator.SPLIT_SUMMARY_TABLE
    assert output["reviews_table"] == signal_quality_split_evaluator.SPLIT_REVIEWS_TABLE
    assert output["decisions_table"] == signal_quality_split_evaluator.SPLIT_DECISIONS_TABLE
    assert output["authority"] == "research_only_schema_maintenance"
    assert output["broker_execution_allowed"] is False
    assert output["policy_auto_promotion_allowed"] is False


