def test_llm_provenance_audit_missing_check_records_fallback(monkeypatch):
    class AmbiguousMissing:
        pass

    events: list[dict[str, object]] = []
    sentinel = AmbiguousMissing()
    monkeypatch.setattr(llm_provenance_audit.pd, "isna", lambda _value: (_ for _ in ()).throw(TypeError("ambiguous missing")))
    monkeypatch.setattr(llm_provenance_audit, "record_local_fallback_event", lambda **kwargs: events.append(kwargs) or kwargs)

    assert llm_provenance_audit._is_missing(sentinel) is False
    assert events[0]["fallback_type"] == "llm_provenance_missing_check_failed"
    assert events[0]["source"] == "is_missing"
    assert events[0]["metadata"] == {"value_type": "AmbiguousMissing"}


def test_llm_provenance_audit_table_failure_records_fallback(monkeypatch):
    events: list[dict[str, object]] = []
    monkeypatch.setattr(llm_provenance_audit, "record_local_fallback_event", lambda **kwargs: events.append(kwargs) or kwargs)
    monkeypatch.setattr(
        llm_provenance_audit,
        "load_recent_rows",
        lambda spec, **_kwargs: (_ for _ in ()).throw(RuntimeError(f"{spec.label} unavailable")),
    )

    payload = llm_provenance_audit.build_llm_provenance_audit(lookback_days=7, limit_per_table=10)

    assert payload["status"] == "issues_found"
    assert payload["issue_table_count"] == len(llm_provenance_audit.PROVENANCE_SPECS)
    assert {row["status"] for row in payload["tables"]} == {"load_failed"}
    assert events[0]["fallback_type"] == "llm_provenance_table_audit_failed"
    assert events[0]["source"] == llm_provenance_audit.PROVENANCE_SPECS[0].table_name
    assert events[0]["metadata"]["prompt_id"] == llm_provenance_audit.PROVENANCE_SPECS[0].prompt_id


def test_llm_provenance_audit_build_payload_handles_missing_table(monkeypatch):
    monkeypatch.setattr(llm_provenance_audit, "_table_exists", lambda table_name: False)

    payload = llm_provenance_audit.build_llm_provenance_audit(lookback_days=7, limit_per_table=10)

    assert payload["status"] == "issues_found"
    assert payload["issue_table_count"] == len(llm_provenance_audit.PROVENANCE_SPECS)
    assert {row["status"] for row in payload["tables"]} == {"missing_table"}
    assert payload["policy_boundary"]["broker_execution_allowed"] is False
